INSERT INTO `wp_options` VALUES (442,'options_about_page_narrative_1','PT Bank Perekonomian Rakyat Syariah (BPRS) Wakalumi didirikan oleh Yayasan Wakalumi (Wakaf Karyawan dan Alumni Muslim Citibank) berdasarkan Surat Menteri Keuangan Republik Indonesia Nomor S-637/MK.13/1989 tanggal 18 Mei 1989 tentang Persetujuan Prinsip Pendirian Bank Perkreditan Rakyat, yang ditujukan kepada Drs. Amir R. Batubara dan ditandatangani oleh Direktur Jenderal Moneter, Bambang Subianto. PT Bank Perekonomian Rakyat Syariah (BPRS) Wakalumi kemudian resmi berdiri berdasarkan Akta Notaris Ny. Siti Pertiwi Henny Shidki, SH Nomor 59 tanggal 7 Oktober 1989 dan memperoleh pengesahan Menteri Kehakiman Republik Indonesia pada tanggal 13 Januari 1990. dan pada tahun 1995 BPRS Wakalumi secara resmi dikonversi menjadi Bank Pembiayaan Rakyat Syariah berlandaskan Undang-Undang Nomor 7 Tahun 1992.','auto');
INSERT INTO `wp_options` VALUES (443,'options_about_page_narrative_2','Bank Syariah Wakalumi senantiasa berpegang teguh pada komitmen ISHLAH—terus melakukan perbaikan berkelanjutan demi kemaslahatan bersama. Kami menghimpun dana dari masyarakat dalam bentuk deposito berjangka dan tabungan syariah, memberikan pembiayaan bagi pengusaha kecil, mikro, maupun masyarakat umum, serta aktif memfasilitasi literasi ekonomi syariah dan pembinaan Bank Mini di sekolah-sekolah.','auto');
