INSERT INTO `wp_options` VALUES (456,'options_about_page_missions','a:5:{i:0;a:2:{s:5:\"title\";s:35:\"Meningkatkan Kepercayaan dan Amanah\";s:4:\"desc\";s:171:\"Menjalankan seluruh aktivitas perbankan sesuai prinsip syariah dengan transparansi, akuntabilitas, dan integritas, sehingga menjadi lembaga yang dipercaya oleh masyarakat.\";}i:1;a:2:{s:5:\"title\";s:42:\"Menjaga Kesehatan Keuangan dan Tata Kelola\";s:4:\"desc\";s:166:\"Menerapkan manajemen risiko yang ketat, pengelolaan aset yang bijak, serta tata kelola perusahaan yang profesional untuk memastikan keberlanjutan dan stabilitas bank.\";}i:2;a:2:{s:5:\"title\";s:25:\"Mendorong Inovasi Layanan\";s:4:\"desc\";s:163:\"Mengembangkan produk dan layanan berbasis teknologi yang sesuai regulasi, sehingga memudahkan akses nasabah dan mendukung transformasi menuju bank syariah digital.\";}i:3;a:2:{s:5:\"title\";s:37:\"Memberdayakan UMKM dan Komunitas Umat\";s:4:\"desc\";s:141:\"Menyediakan pembiayaan yang adil, inklusif, dan berorientasi pada pemberdayaan ekonomi umat, khususnya sektor UMKM dan usaha mikro di daerah.\";}i:4;a:2:{s:5:\"title\";s:34:\"Membangun Kedekatan dengan Nasabah\";s:4:\"desc\";s:195:\"Menjalin hubungan yang hangat dan solutif dengan nasabah melalui pelayanan personal, penggunaan teknologi, edukasi keuangan syariah, serta program sosial yang relevan dengan kebutuhan masyarakat.\";}}','auto');
INSERT INTO `wp_options` VALUES (457,'options_about_page_identity','Bank Syariah Wakalumi adalah Lembaga Keuangan Syariah yang memiliki fokus pada jasa keuangan dan pemberdayaan ekonomi umat dan masyarakat sesuai syariah.','auto');
INSERT INTO `wp_options` VALUES (458,'options_about_page_belief','BSW berkomitmen untuk selalu melakukan ISHLAH, yakni kami terus melakukan perbaikan berkelanjutan.','auto');
INSERT INTO `wp_options` VALUES (459,'options_about_page_values','a:4:{i:0;a:3:{s:7:\"acronym\";s:1:\"W\";s:5:\"title\";s:26:\"Wisdom (Fathanah & Siddiq)\";s:4:\"desc\";s:119:\"Menyoroti kearifan, integritas, dan kecerdasan dalam mengambil keputusan finansial berbasis syariah yang tepat sasaran.\";}i:1;a:3:{s:7:\"acronym\";s:1:\"A\";s:5:\"title\";s:23:\"Accountability (Amanah)\";s:4:\"desc\";s:131:\"Mencerminkan komitmen penuh terhadap transparansi, tata kelola yang bertanggung jawab, dan keandalan dalam memegang amanah nasabah.\";}i:2;a:3:{s:7:\"acronym\";s:1:\"Q\";s:5:\"title\";s:28:\"Quality (Tabligh & Fathanah)\";s:4:\"desc\";s:141:\"Menekankan keunggulan layanan, penyampaian komunikasi yang jelas, serta standar operasional terbaik demi memberikan manfaat berkesinambungan.\";}i:3;a:3:{s:7:\"acronym\";s:1:\"F\";s:5:\"title\";s:36:\"Foresight (Fathanah & Semangat Waqf)\";s:4:\"desc\";s:155:\"Menggambarkan visi jangka panjang yang berfokus pada inovasi, pertumbuhan produktif, dan keberlanjutan (sustainability) investasi untuk generasi mendatang.\";}}','auto');
