INSERT INTO `wp_options` VALUES (516,'options_pengurus_list','a:6:{i:0;a:10:{s:4:\"nama\";s:20:\"Haryanto, S.E., M.M.\";s:8:\"kategori\";s:22:\"Dewan Pengawas Syariah\";s:7:\"jabatan\";s:28:\"Ketua Dewan Pengawas Syariah\";s:4:\"foto\";s:114:\"http://wakalumibprscoid.local/wp-content/uploads/2026/10/PXL_20260326_080858491.PORTRAIT-scaled-e1793061753113.jpg\";s:13:\"riwayat_karir\";s:285:\"• Ketua Dewan Pengawas Syariah Bank Syariah Wakalumi (BSW) (2024 – saat ini)\r\n• Dewan Pengawas Syariah PT. BPRS Al-Hijrah Amanah\r\n• Dewan Pengawas Syariah Asuransi Ramayana Syariah\r\n• Praktisi dan konsultan akuntansi, audit keuangan, dan kepatuhan perbankan syariah nasional.\";s:10:\"pendidikan\";s:215:\"• Magister Manajemen (S2) Manajemen Keuangan, Universitas Krisnadwipayana (UNKRIS) Jakarta, Lulus Tahun 2004.\r\n• Sarjana Ekonomi (S1) Akuntansi, Universitas Islam As-Syafi\'iyah (UNIAT) Jakarta, Lulus Tahun 1998.\";s:11:\"sertifikasi\";s:94:\"Sertifikasi Dewan Pengawas Syariah (DSN-MUI / LSP-KS), Sertifikasi Akuntansi Keuangan Syariah.\";s:7:\"kutipan\";s:2:\"--\";s:6:\"status\";s:5:\"Aktif\";s:6:\"urutan\";i:1;}i:1;a:10:{s:4:\"nama\";s:20:\"Drs. H. Zarkasih Nur\";s:8:\"kategori\";s:22:\"Dewan Pengawas Syariah\";s:7:\"jabatan\";s:30:\"Anggota Dewan Pengawas Syariah\";s:4:\"foto\";s:77:\"http://wakalumibprscoid.local/wp-content/uploads/2026/10/KPN_Zarkasih_Nur.png\";s:13:\"riwayat_karir\";s:394:\"• Anggota Dewan Pengawas Syariah Bank Syariah Wakalumi (BSW) (sebelumnya menjabat Ketua DPS Bank Syariah Wakalumi)\r\n• Menteri Negara Koperasi dan UKM Republik Indonesia pada Kabinet Persatuan Nasional (1999 – 2001)\r\n• Pimpinan Fraksi & Ketua DPP Partai Persatuan Pembangunan (1998 – 2003)\r\n• Anggota DPR / MPR RI (1987 – 1999)\r\n• Anggota DPRD Kabupaten Tangerang (1971 – 1977)\";s:10:\"pendidikan\";s:119:\"Sarjana (Drs.) Ilmu Keagamaan Islam, IAIN Syarif Hidayatullah Jakarta (kini UIN Syarif Hidayatullah), Lulus Tahun 1973.\";s:11:\"sertifikasi\";s:99:\"Sertifikasi Dewan Pengawas Syariah (DSN-MUI), Tokoh Nasional Penggerak Koperasi & Keuangan Syariah.\";s:7:\"kutipan\";s:2:\"--\";s:6:\"status\";s:5:\"Aktif\";s:6:\"urutan\";i:2;}i:2;a:10:{s:4:\"nama\";s:15:\"Ir. Budi Satoto\";s:8:\"kategori\";s:15:\"Dewan Komisaris\";s:7:\"jabatan\";s:15:\"Komisaris Utama\";s:4:\"foto\";s:103:\"http://wakalumibprscoid.local/wp-content/uploads/2026/10/WhatsApp-Image-2026-10-29-at-7.03.06-PM-1.jpeg\";s:13:\"riwayat_karir\";s:782:\"• Komisaris Utama Bank Syariah Wakalumi (BSW) (2008 – sekarang)\r\n• Ketua Dewan Pengawas KSPPS Koperasi Asy Syirkah Muamalah Indonesia (2017 – sekarang)\r\n• Komisaris Utama PT. BPRS Al-Hijrah Amanah (2017 – sekarang)\r\n• Dosen Tamu IPB & Universitas YARSI (1995 – 2003, 2011 – 2018)\r\n• Komisaris PT FPS Indonesia (member of FPS Group, Singapore) (2013 – 2018)\r\n• Komisaris BPRS Rif\'atul Ummah (2006)\r\n• Corporate Business & Secretary PT Iska Niaga Darma, Holding Company (2004 – 2018)\r\n• Direktur Keuangan PT Asuransi Syariah Mubarakah (2002 – 2003)\r\n• Auditor BPPN Badan Penyehatan Perbankan Nasional, KAP Heliantono & Basyiruddin - BPPN (2000)\r\n• Dept. Head (Kredit program) Bank Nusa (1994 – 2000)\r\n• Account Officer Bank Duta (1989 – 1994)\";s:10:\"pendidikan\";s:101:\"Sarjana (S1) Program Studi Agrometeorologi, FMIPA - Institut Pertanian Bogor (IPB), Lulus Tahun 1998.\";s:11:\"sertifikasi\";s:93:\"Sertifikasi Kompetensi Komisaris BPR/BPRS (OJK / Certif), Manajemen Risiko Perbankan Syariah.\";s:7:\"kutipan\";s:2:\"--\";s:6:\"status\";s:5:\"Aktif\";s:6:\"urutan\";i:3;}i:3;a:10:{s:4:\"nama\";s:24:\"Rena Bangun Luhur, S.Pd.\";s:8:\"kategori\";s:15:\"Dewan Komisaris\";s:7:\"jabatan\";s:9:\"Komisaris\";s:4:\"foto\";s:102:\"http://wakalumibprscoid.local/wp-content/uploads/2026/10/WhatsApp-Image-2026-09-23-at-11.44.45-AM.jpeg\";s:13:\"riwayat_karir\";s:424:\"• Dewan Komisaris Bank Syariah Wakalumi (BSW) (2024 – saat ini)\r\n• Manajer Operasional KSPPS Tamzis Bina Utama (2022 – saat ini)\r\n• Manajer Kantor Pelayanan Operasional (KPO) KSPPS Tamzis Bina Utama (2018 – 2022)\r\n• Manajer Marketing Wilayah KSPPS Tamzis Bina Utama (2012 – 2018)\r\n• Manajer Marketing Area KSPPS Tamzis Bina Utama (2009 – 2012)\r\n• Manajer Marketing Cabang KSPPS Tamzis Bina Utama (2009)\";s:10:\"pendidikan\";s:119:\"Sarjana (S1) Fakultas Ilmu Sosial / Pendidikan Ekonomi Koperasi, Universitas Negeri Yogyakarta (UNY), Lulus Tahun 2004.\";s:11:\"sertifikasi\";s:101:\"Sertifikasi Kompetensi Komisaris BPR/BPRS (OJK), Manajemen Operasional & IT Lembaga Keuangan Syariah.\";s:7:\"kutipan\";s:2:\"--\";s:6:\"status\";s:5:\"Aktif\";s:6:\"urutan\";i:4;}i:4;a:10:{s:4:\"nama\";s:26:\"Kiftiah Hindun, S.P., M.M.\";s:8:\"kategori\";s:7:\"Direksi\";s:7:\"jabatan\";s:14:\"Direktur Utama\";s:4:\"foto\";s:117:\"http://wakalumibprscoid.local/wp-content/uploads/2026/10/WhatsApp-Image-2026-09-23-at-11.45.08-AM-e1792482502383.jpeg\";s:13:\"riwayat_karir\";s:676:\"• Direktur Utama yang Membawahkan Fungsi Kepatuhan PT BPR Syariah Wakalumi (BSW) (Oktober 2026 – saat ini)\r\n• Manajer IT & Pelaporan PT. BPRS Baiturridha Pusaka (Januari 2025 – 2026 September)\r\n• Direktur Operasional yang Membawahkan Fungsi Kepatuhan PT. BPRS AlSalaam Amal Salman (2021 – 2025)\r\n• Direktur Operasional PT. BPRS AlSalaam Amal Salman (2017 – 2021)\r\n• Kepala Divisi Operasional & Funding PT. BPRS AlSalaam Amal Salman (2014 – 2017)\r\n• Kepala Cabang PT. BPRS AlSalaam Amal Salman (2012 – 2014)\r\n• Supervisor Layanan & Operasional PT. BPRS AlSalaam Amal Salman (2006 – 2012)\r\n• Management Trainee PT.BPR Amal Salman (Okt 2003 sd 2006)\";s:10:\"pendidikan\";s:152:\"• Magister Manajemen (S2), UPN Veteran Jawa Timur, Lulus Tahun 2026.\r\n• Sarjana Pertanian (S1), Universitas Brawijaya (UB) Malang, Lulus Tahun 2002.\";s:11:\"sertifikasi\";s:111:\"Sertifikasi Direktur BPR/BPRS Tingkat II (OJK / Certif), Sertifikasi Manajemen Risiko Perbankan Syariah (BNSP).\";s:7:\"kutipan\";s:2:\"--\";s:6:\"status\";s:5:\"Aktif\";s:6:\"urutan\";i:5;}i:5;a:10:{s:4:\"nama\";s:20:\"Lukman Nugroho, S.E.\";s:8:\"kategori\";s:7:\"Direksi\";s:7:\"jabatan\";s:15:\"Direktur Bisnis\";s:4:\"foto\";s:114:\"http://wakalumibprscoid.local/wp-content/uploads/2026/10/WhatsApp-Image-2026-09-22-at-2-removebackgrounds-ai-1.png\";s:13:\"riwayat_karir\";s:276:\"• Direktur Bisnis Bank Syariah Wakalumi (BSW) (Oktober 2026 – saat ini)\r\n• Manajer Marketing Area KSPPS Tamzis Bina Utama (2013 – 2026)\r\n• Manajer Marketing Cabang KSPPS Tamzis Bina Utama (2007 – 2013)\r\n• Marketing Officer KSPPS Tamzis Bina Utama (2005 – 2007)\";s:10:\"pendidikan\";s:93:\"Sarjana Ekonomi (S1) Program Studi Manajemen, STIE Widya Wiwaha Yogyakarta, Lulus Tahun 2016.\";s:11:\"sertifikasi\";s:119:\"Sertifikasi Direksi BPR/BPRS (OJK), Sertifikasi Manajemen Risiko Perbankan Syariah, Analisis Pembiayaan Produktif UMKM.\";s:7:\"kutipan\";s:2:\"--\";s:6:\"status\";s:5:\"Aktif\";s:6:\"urutan\";i:6;}}','auto');
