INSERT INTO `wp_options` VALUES (637,'options_tabungan_faq_subtitle','Pertanyaan umum nasabah seputar produk simpanan syariah, keamanan simpanan di LPS, dan prosedur pembukaan rekening.','auto');
INSERT INTO `wp_options` VALUES (638,'options_tabungan_faq_list','a:5:{i:0;a:2:{s:1:\"q\";s:48:\"Bagaimana cara membuka rekening tabungan di BSW?\";s:1:\"a\";s:285:\"Anda dapat langsung mengunjungi salah satu jaringan kantor operasional kami (Kantor Pusat Ciputat, atau Kantor Kas Cikupa) dengan membawa kartu identitas (e-KTP). Anda juga dapat menghubungi Customer Service via WhatsApp untuk mendapatkan layanan jemput setoran atau pendampingan awal.\";}i:1;a:2:{s:1:\"q\";s:70:\"Apakah ada potongan biaya administrasi bulanan pada rekening tabungan?\";s:1:\"a\";s:141:\"Tidak ada. Seluruh produk tabungan BSW bebas biaya administrasi bulanan, sehingga saldo tabungan Anda tetap utuh terjaga dan tidak berkurang.\";}i:2;a:2:{s:1:\"q\";s:56:\"Apakah dana simpanan tabungan saya aman dan dijamin LPS?\";s:1:\"a\";s:226:\"Sangat aman. BSW adalah bank peserta penjaminan Lembaga Penjamin Simpanan (LPS) dengan batas penjaminan hingga Rp 2 Miliar per nasabah per bank, serta beroperasi dengan izin resmi dan diawasi oleh Otoritas Jasa Keuangan (OJK).\";}i:3;a:2:{s:1:\"q\";s:70:\"Apa perbedaan antara akad Mudharabah dan Wadiah pada tabungan syariah?\";s:1:\"a\";s:323:\"Akad Wadiah adalah titipan murni di mana nasabah menitipkan dana tanpa janji bagi hasil tetap (dapat berupa bonus sukarela). Sedangkan akad Mudharabah adalah kerja sama investasi syariah di mana dana nasabah dikelola secara produktif oleh bank dan keuntungan dibagikan setiap bulan sesuai nisbah bagi hasil yang disepakati.\";}i:4;a:2:{s:1:\"q\";s:55:\"Apakah BSW menyediakan layanan jemput setoran tabungan?\";s:1:\"a\";s:239:\"Ya, Bank Syariah Wakalumi menyediakan fasilitas layanan jemput setoran (pick-up service) bagi nasabah perorangan maupun pedagang/pelaku usaha UMKM untuk memudahkan menabung tanpa perlu repot meninggalkan tempat usaha atau aktivitas harian.\";}}','auto');
