INSERT INTO `wp_options` VALUES (866,'options_pembiayaan_list','a:8:{i:0;a:16:{s:4:\"nama\";s:15:\"Pembiayaan UMKM\";s:4:\"slug\";s:4:\"umkm\";s:7:\"tagline\";s:46:\"Solusi Cepat Permodalan Usaha & Pedagang Pasar\";s:5:\"badge\";s:15:\"Pedagang & UMKM\";s:5:\"color\";s:6:\"orange\";s:4:\"akad\";s:35:\"Murabahah / Mudharabah / Musyarakah\";s:13:\"limit_primary\";s:31:\"Plafon Rp 5 Jt s.d. Rp 100 Juta\";s:15:\"limit_secondary\";s:21:\"Tenor 6 s.d. 36 Bulan\";s:4:\"desc\";s:211:\"Fokus pembiayaan kepada Pedagang demi membantu pertumbuhan Usaha dan UMKM secara keseluruhan. Skema angsuran harian/mingguan/bulanan yang ringan disesuaikan dengan perputaran arus kas usaha pasar dan ritel Anda.\";s:10:\"keunggulan\";s:204:\"Proses cepat dan persyaratan mudah bersahabat\r\nFasilitas layanan jemput angsuran langsung ke lokasi usaha / pasar\r\nTanpa potongan biaya siluman dan bebas riba\r\nAkad syariah transparan dan menenangkan hati\";s:6:\"syarat\";s:222:\"Fotokopi e-KTP Pemohon dan Suami/Istri (jika sudah menikah)\r\nFotokopi Kartu Keluarga (KK) & Surat Nikah\r\nSurat Keterangan Usaha (SKU) dari Kelurahan / Pengelola Pasar\r\nBukti transaksi atau catatan pembukuan usaha sederhana\";s:7:\"wa_text\";s:152:\"Halo Bank Syariah Wakalumi, saya tertarik mengajukan Pembiayaan 1000 Pedagang untuk penambahan modal usaha saya. Mohon informasi syarat dan prosedurnya.\";s:4:\"icon\";s:5:\"store\";s:5:\"image\";s:66:\"http://wakalumibprscoid.local/wp-content/uploads/2026/10/umkm.jpeg\";s:10:\"custom_svg\";s:0:\"\";s:6:\"urutan\";i:1;}i:1;a:16:{s:4:\"nama\";s:15:\"Pembiayaan Guru\";s:4:\"slug\";s:4:\"guru\";s:7:\"tagline\";s:47:\"Dukungan Kesejahteraan & Sarana Tenaga Pendidik\";s:5:\"badge\";s:26:\"Guru & Tenaga Kependidikan\";s:5:\"color\";s:6:\"indigo\";s:4:\"akad\";s:28:\"Murabahah / Ijarah Multijasa\";s:13:\"limit_primary\";s:30:\"Plafon Rp 5 Jt s.d. Rp 50 Juta\";s:15:\"limit_secondary\";s:22:\"Tenor 12 s.d. 60 Bulan\";s:4:\"desc\";s:245:\"Fokus pembiayaan sebagai sarana memenuhi kebutuhan Guru dan Pengajar dalam menjalankan tugas dan tanggung jawab. Dapat dimanfaatkan untuk kepemilikan laptop/perangkat ajar, renovasi tempat tinggal, pendidikan lanjutan, hingga kebutuhan keluarga.\";s:10:\"keunggulan\";s:223:\"Margin syariah istimewa bagi para pahlawan tanpa tanda jasa\r\nPembayaran angsuran terkoordinasi dengan bendahara sekolah/yayasan\r\nJangka waktu fleksibel hingga 5 tahun (60 bulan)\r\nBebas penalti dan biaya pelunasan dipercepat\";s:6:\"syarat\";s:202:\"Fotokopi e-KTP & Kartu Keluarga\r\nSK Pengangkatan Guru / Surat Rekomendasi Kepala Sekolah/Yayasan\r\nSlip gaji atau mutasi rekening koran 3 bulan terakhir\r\nKartu Tanda Anggota (KTA) Guru / NUPTK (jika ada)\";s:7:\"wa_text\";s:153:\"Halo Bank Syariah Wakalumi, saya guru/tenaga pendidik yang berminat dengan program Pembiayaan 1000 Guru. Mohon informasi syarat dan simulasi angsurannya.\";s:4:\"icon\";s:9:\"education\";s:5:\"image\";s:70:\"http://wakalumibprscoid.local/wp-content/uploads/2026/10/pendidik.jpeg\";s:10:\"custom_svg\";s:0:\"\";s:6:\"urutan\";i:2;}i:2;a:16:{s:4:\"nama\";s:35:\"Pembiayaan Al-Murabahah (Jual Beli)\";s:4:\"slug\";s:9:\"murabahah\";s:7:\"tagline\";s:41:\"Kepemilikan Barang & Pengadaan Aset Usaha\";s:5:\"badge\";s:24:\"Perorangan & Badan Usaha\";s:5:\"color\";s:4:\"teal\";s:4:\"akad\";s:12:\"Al-Murabahah\";s:13:\"limit_primary\";s:32:\"Plafon Rp 10 Jt s.d. Rp 1 Miliar\";s:15:\"limit_secondary\";s:22:\"Tenor 12 s.d. 60 Bulan\";s:4:\"desc\";s:235:\"Pembiayaan dengan prinsip jual beli barang pada harga asal dengan tambahan keuntungan (margin) yang disepakati, dengan pihak bank selaku penjual dan nasabah selaku pembeli. Besaran angsuran bersifat tetap (flat) selama masa pembiayaan.\";s:10:\"keunggulan\";s:279:\"Kepastian jumlah angsuran tetap setiap bulan dari awal hingga lunas\r\nObjek barang langsung menjadi milik nasabah secara sah sejak akad\r\nDapat digunakan untuk mesin produksi, material bahan baku, kendaraan operasional, dll\r\nBebas dari fluktuasi suku bunga konvensional (anti-riba)\";s:6:\"syarat\";s:184:\"Fotokopi e-KTP, KK, & NPWP Pribadi/Badan Usaha\r\nSurat penawaran harga / invoice barang yang akan dibeli\r\nDokumen legalitas usaha (NIB/SIUP, TDP)\r\nDokumen jaminan/agunan (SHM/SHGB/BPKB)\";s:7:\"wa_text\";s:152:\"Halo Bank Syariah Wakalumi, saya ingin berkonsultasi mengenai Pembiayaan Murabahah untuk pengadaan aset/barang. Mohon rincian persyaratan dan prosesnya.\";s:4:\"icon\";s:4:\"cart\";s:5:\"image\";s:82:\"http://wakalumibprscoid.local/wp-content/uploads/2026/10/pembiayaan-murabahah.jpeg\";s:10:\"custom_svg\";s:0:\"\";s:6:\"urutan\";i:3;}i:3;a:16:{s:4:\"nama\";s:43:\"Pembiayaan Al-Mudharabah (Bagi Hasil Usaha)\";s:4:\"slug\";s:10:\"mudharabah\";s:7:\"tagline\";s:36:\"Kemitraan Modal Kerja 100% dari Bank\";s:5:\"badge\";s:23:\"Pengusaha & Sektor Riil\";s:5:\"color\";s:7:\"emerald\";s:4:\"akad\";s:13:\"Al-Mudharabah\";s:13:\"limit_primary\";s:34:\"Plafon Rp 25 Jt s.d. Rp 1.5 Miliar\";s:15:\"limit_secondary\";s:22:\"Tenor 12 s.d. 36 Bulan\";s:4:\"desc\";s:257:\"Pembiayaan dengan prinsip bagi hasil yang sesuai dengan kesepakatan rasio nisbah. Bank menyediakan 100% kebutuhan modal kerja dan nasabah mengelola keahlian operasional usaha. Disalurkan untuk perdagangan, industri manufaktur, pertanian, dan jasa komersial.\";s:10:\"keunggulan\";s:270:\"Sistem bagi hasil adil mengikuti realitas perolehan pendapatan usaha berjalan\r\nBank bertindak sebagai mitra strategis kemajuan bisnis Anda\r\nLaporan keuangan dikawal secara transparan dan profesional\r\nSangat cocok untuk proyek atau kontrak kerja yang sudah pasti (SPK/PO)\";s:6:\"syarat\";s:230:\"Company Profile / Rencana Kerja Bisnis (Feasibility Study)\r\nLaporan Keuangan / Rekening Koran Usaha 6 bulan terakhir\r\nLegalitas Usaha Lengkap (Akta, NIB, NPWP)\r\nSurat Perintah Kerja (SPK) / Purchase Order (PO) bila berbasis proyek\";s:7:\"wa_text\";s:150:\"Halo Bank Syariah Wakalumi, saya memerlukan pembiayaan modal kerja Mudharabah berbasis bagi hasil untuk proyek/usaha saya. Mohon informasi konsultasi.\";s:4:\"icon\";s:5:\"chart\";s:5:\"image\";s:72:\"http://wakalumibprscoid.local/wp-content/uploads/2026/10/mudharabah.jpeg\";s:10:\"custom_svg\";s:0:\"\";s:6:\"urutan\";i:4;}i:4;a:16:{s:4:\"nama\";s:43:\"Pembiayaan Al-Musyarakah (Penyertaan Modal)\";s:4:\"slug\";s:10:\"musyarakah\";s:7:\"tagline\";s:49:\"Ekspansi Bisnis dengan Penggabungan Modal Bersama\";s:5:\"badge\";s:27:\"Kemitraan Usaha & Korporasi\";s:5:\"color\";s:4:\"blue\";s:4:\"akad\";s:13:\"Al-Musyarakah\";s:13:\"limit_primary\";s:32:\"Plafon Rp 50 Jt s.d. Rp 2 Miliar\";s:15:\"limit_secondary\";s:22:\"Tenor 12 s.d. 60 Bulan\";s:4:\"desc\";s:274:\"Pembiayaan dengan prinsip bagi hasil di mana bank dan nasabah sama-sama menyertakan porsi modal usaha. Porsi keuntungan disesuaikan dengan kesepakatan rasio bersama. Solusi tepat bagi Anda yang telah memiliki usaha aktif dan bermaksud mengembangkan kapasitas skala usahanya.\";s:10:\"keunggulan\";s:292:\"Rasio keuntungan disepakati adil di awal sesuai porsi dan kontribusi kemitraan\r\nMendorong akselerasi pertumbuhan skala bisnis menengah dan korporasi lokal\r\nFleksibilitas pembayaran dividen/bagi hasil sesuai siklus penerimaan omzet\r\nPengawasan terpadu berstandar tata kelola syariah yang sehat\";s:6:\"syarat\";s:222:\"Laporan neraca laba rugi usaha minimal 1 tahun terakhir\r\nDokumen legalitas usaha berbadan hukum (PT/CV/Koperasi)\r\nBukti penyertaan modal sendiri (equity sharing)\r\nDokumen jaminan kebendaan sebagai mitigasi risiko kepatuhan\";s:7:\"wa_text\";s:135:\"Halo Bank Syariah Wakalumi, saya ingin mendiskusikan pembiayaan modal kerja Musyarakah untuk pengembangan skala bisnis perusahaan kami.\";s:4:\"icon\";s:9:\"handshake\";s:5:\"image\";s:76:\"http://wakalumibprscoid.local/wp-content/uploads/2026/09/1000307759.jpg.jpeg\";s:10:\"custom_svg\";s:0:\"\";s:6:\"urutan\";i:5;}i:5;a:16:{s:4:\"nama\";s:48:\"Pembiayaan Ijarah & IMBT (Sewa & Sewa Beli Aset)\";s:4:\"slug\";s:6:\"ijarah\";s:7:\"tagline\";s:45:\"Sewa Tempat Usaha & Pemindahan Hak Milik Aset\";s:5:\"badge\";s:22:\"Usaha Komersial & Jasa\";s:5:\"color\";s:4:\"cyan\";s:4:\"akad\";s:35:\"Ijarah & Ijarah Muntahiya Bittamlik\";s:13:\"limit_primary\";s:32:\"Plafon Rp 20 Jt s.d. Rp 750 Juta\";s:15:\"limit_secondary\";s:22:\"Tenor 12 s.d. 48 Bulan\";s:4:\"desc\";s:244:\"Pembiayaan dengan prinsip sewa murni atau sewa beli (IMBT). Sangat sesuai untuk Anda yang menginginkan sewa tempat usaha, ruko, kios, atau penambahan aset modal yang pada akhirnya dialihkan kepemilikannya kepada Anda di akhir masa periode sewa.\";s:10:\"keunggulan\";s:294:\"Kemudahan mendapatkan manfaat penggunaan aset produktif tanpa harus bayar tunai di muka\r\nPilihan opsi pemindahan kepemilikan aset (hibah atau jual) di akhir masa sewa\r\nUjrah (biaya sewa) jelas dan disepakati di muka tanpa kejutan bunga\r\nMenjaga arus kas likuiditas usaha tetap sehat dan leluasa\";s:6:\"syarat\";s:206:\"Draft Surat Perjanjian Sewa / Brosur Ruko / Spesifikasi Aset yang disewa\r\nFotokopi identitas pemohon dan legalitas usaha\r\nRekening koran operasional 3 bulan terakhir\r\nJaminan pelengkap sesuai ketentuan bank\";s:7:\"wa_text\";s:139:\"Halo Bank Syariah Wakalumi, saya ingin mengajukan pembiayaan sewa tempat usaha / Ijarah IMBT. Mohon informasi persyaratan dan ketentuannya.\";s:4:\"icon\";s:8:\"building\";s:5:\"image\";s:76:\"http://wakalumibprscoid.local/wp-content/uploads/2026/09/1000307750.jpg.jpeg\";s:10:\"custom_svg\";s:0:\"\";s:6:\"urutan\";i:6;}i:6;a:16:{s:4:\"nama\";s:54:\"Pembiayaan Multijasa (Ujrah Jasa / Umroh / Pendidikan)\";s:4:\"slug\";s:9:\"multijasa\";s:7:\"tagline\";s:52:\"Paket Ibadah Umroh, Pendidikan Lanjutan & Biaya Jasa\";s:5:\"badge\";s:21:\"Keluarga & Perorangan\";s:5:\"color\";s:6:\"purple\";s:4:\"akad\";s:26:\"Ijarah Multijasa / Kafalah\";s:13:\"limit_primary\";s:32:\"Plafon Rp 10 Jt s.d. Rp 150 Juta\";s:15:\"limit_secondary\";s:21:\"Tenor 6 s.d. 36 Bulan\";s:4:\"desc\";s:290:\"Pembiayaan dengan menggunakan akad Ijarah atau Kafalah di mana bank memperoleh imbalan jasa (ujrah) atas penyediaan fasilitas jasa bagi nasabah. Besarnya ujrah disepakati di awal dalam bentuk nominal pasti untuk paket ibadah umroh, biaya pendidikan tinggi, renovasi, atau layanan kesehatan.\";s:10:\"keunggulan\";s:267:\"Nominal imbalan jasa (ujrah) pasti dan tetap tanpa perubahan di tengah jalan\r\nMembantu mewujudkan niat ibadah suci ke tanah suci tanpa kendala tunai\r\nProses persetujuan cepat dengan syarat bersahabat\r\nPilihan tenor fleksibel sesuai kemampuan angsuran bulanan keluarga\";s:6:\"syarat\";s:214:\"Fotokopi e-KTP suami & istri, Kartu Keluarga, dan Surat Nikah\r\nSlip penghasilan / bukti pendapatan bulanan\r\nKwitansi / Invoice resmi dari biro travel umroh atau institusi penyedia jasa\r\nDokumen jaminan yang memadai\";s:7:\"wa_text\";s:151:\"Halo Bank Syariah Wakalumi, saya ingin berkonsultasi mengenai Pembiayaan Multijasa (Umroh/Pendidikan). Mohon rincian paket simulasi dan persyaratannya.\";s:4:\"icon\";s:5:\"plane\";s:5:\"image\";s:76:\"http://wakalumibprscoid.local/wp-content/uploads/2026/09/1000307744.jpg.jpeg\";s:10:\"custom_svg\";s:0:\"\";s:6:\"urutan\";i:7;}i:7;a:16:{s:4:\"nama\";s:50:\"Pembiayaan Qardhul Hasan (Kebijakan Sosial Dhuafa)\";s:4:\"slug\";s:5:\"qardh\";s:7:\"tagline\";s:51:\"Pinjaman Kebajikan Murni Tanpa Tambahan Bagi Dhuafa\";s:5:\"badge\";s:20:\"Sosial & Kaum Dhuafa\";s:5:\"color\";s:7:\"emerald\";s:4:\"akad\";s:16:\"Al-Qardhul Hasan\";s:13:\"limit_primary\";s:29:\"Plafon Ringan s.d. Rp 10 Juta\";s:15:\"limit_secondary\";s:26:\"Tenor Fleksibel Musyawarah\";s:4:\"desc\";s:241:\"Pembiayaan kebijakan dengan prinsip pinjam meminjam murni tanpa ada tambahan (bunga/margin nol persen). Diperuntukkan bagi kaum dhuafa atau pengusaha ultra mikro yang berikhtiar mengembangkan usaha kecilnya demi kemandirian ekonomi keluarga.\";s:10:\"keunggulan\";s:263:\"Bebas dari tambahan margin maupun bunga (0% murni tanpa riba)\r\nPengembalian pokok pinjaman sesuai kesepakatan kemampuan nasabah\r\nWujud kepedulian sosial perbankan syariah terhadap pengentasan kemiskinan\r\nPendampingan berkala agar usaha terus tumbuh dan naik kelas\";s:6:\"syarat\";s:231:\"Surat Keterangan Tidak Mampu (SKTM) atau rekomendasi dari tokoh masyarakat / lembaga zakat\r\ne-KTP dan Kartu Keluarga\r\nRencana usaha sederhana yang sedang/akan dijalankan\r\nKomitmen amanah untuk mengangsur pengembalian pinjaman pokok\";s:7:\"wa_text\";s:137:\"Halo Bank Syariah Wakalumi, saya ingin menanyakan informasi mengenai program sosial Pembiayaan Qardhul Hasan. Mohon petunjuk prosedurnya.\";s:4:\"icon\";s:5:\"heart\";s:5:\"image\";s:0:\"\";s:10:\"custom_svg\";s:0:\"\";s:6:\"urutan\";i:8;}}','auto');
