INSERT INTO `wp_options` VALUES (1348,'options_lelang_desc','Portal resmi publikasi lelang eksekusi Hak Tanggungan dan penjualan Agunan Yang Diambil Alih (AYDA) Bank Syariah Wakalumi. Seluruh proses diselenggarakan secara amanah, transparan, serta mematuhi regulasi POJK dan prinsip syariah DSN-MUI.','auto');
