INSERT INTO `wp_options` VALUES (1371,'options_lelang_cta_desc','Tim Remedial BSW siap mendampingi Anda untuk survei lokasi fisik, pengecekan berkas sertifikat di kantor bank, dan konsultasi skema KPR Syariah.','auto');
