INSERT INTO `wp_options` VALUES (1377,'options_lelang_list','a:3:{i:0;a:22:{s:2:\"id\";s:8:\"lelang_1\";s:4:\"kode\";s:13:\"AYDA-2026-001\";s:5:\"judul\";s:50:\"Toyota Avanza 1.3 G Manual (2006) - Silver Metalik\";s:8:\"kategori\";s:9:\"kendaraan\";s:6:\"status\";s:8:\"tersedia\";s:11:\"harga_limit\";s:13:\"Rp 70.000.000\";s:11:\"nilai_pasar\";s:13:\"Rp 85.000.000\";s:12:\"uang_jaminan\";s:13:\"Rp 14.000.000\";s:9:\"legalitas\";s:58:\"BPKB Asli + STNK Aktif + Faktur Pembelian (Plat B Tangsel)\";s:10:\"luas_tanah\";s:1:\"-\";s:13:\"luas_bangunan\";s:1:\"-\";s:6:\"lokasi\";s:55:\"Jl. Surya Kencana No. 45, Pamulang Barat, Kec. Pamulang\";s:4:\"kota\";s:17:\"Tangerang Selatan\";s:14:\"tanggal_lelang\";s:41:\"Terbuka (Penjualan Sukarela / Siap Pakai)\";s:13:\"tempat_lelang\";s:45:\"Pool Agunan BPRS Wakalumi, Pamulang / Ciputat\";s:10:\"foto_utama\";s:71:\"http://wakalumibprscoid.local/wp-content/uploads/2026/10/2686695983.jpg\";s:11:\"galeri_foto\";s:147:\"http://wakalumibprscoid.local/wp-content/uploads/2026/10/gallery_used-car-mobil123-toyota-avanza-g-mpv-indonesia_0817444_LYlybVC5wW12aYvR1iLJmM.jpg\";s:9:\"deskripsi\";s:431:\"Unit kendaraan roda empat MPV keluarga Toyota Avanza tipe 1.3 G transmisi Manual tahun perakitan 2006 warna Silver Metalik.\r\n\r\nKondisi mesin terawat baik dan kering, tarikan enteng, AC double blower dingin, interior jok original terawat rapi, power window & sistem kelistrikan normal, ban tebal 80%. Dokumen lengkap (BPKB, STNK aktif, faktur asli, kunci cadangan). Unit siap pakai untuk operasional keluarga maupun mobilitas usaha.\";s:9:\"tata_cara\";s:287:\"Aset berstatus Penjualan Sukarela (AYDA) atas persetujuan tertulis nasabah debitur. Peminat dapat langsung mengecek fisik kendaraan di pool agunan BPRS Wakalumi. Pembelian dapat dilakukan secara tunai (cash keras/bertahap) atau diajukan Pembiayaan Kepemilikan Kendaraan Bermotor Syariah.\";s:16:\"kepatuhan_custom\";s:0:\"\";s:10:\"wa_contact\";s:0:\"\";s:6:\"urutan\";i:1;}i:1;a:22:{s:2:\"id\";s:8:\"lelang_2\";s:4:\"kode\";s:13:\"AYDA-2026-002\";s:5:\"judul\";s:56:\"Rumah Tinggal 1 Lantai SHM Asri Pemukiman Warga Sawangan\";s:8:\"kategori\";s:5:\"rumah\";s:6:\"status\";s:8:\"tersedia\";s:11:\"harga_limit\";s:14:\"Rp 220.000.000\";s:11:\"nilai_pasar\";s:14:\"Rp 280.000.000\";s:12:\"uang_jaminan\";s:13:\"Rp 44.000.000\";s:9:\"legalitas\";s:41:\"SHM (Sertifikat Hak Milik) Asli No. 03412\";s:10:\"luas_tanah\";s:6:\"70 m²\";s:13:\"luas_bangunan\";s:6:\"45 m²\";s:6:\"lokasi\";s:56:\"Jl. H. Sulaiman RT 03/RW 04, Kel. Bedahan, Kec. Sawangan\";s:4:\"kota\";s:5:\"Depok\";s:14:\"tanggal_lelang\";s:40:\"Terbuka (Penjualan Sukarela / Siap Huni)\";s:13:\"tempat_lelang\";s:51:\"Kantor Operasional BPRS Wakalumi & On-Site Property\";s:10:\"foto_utama\";s:93:\"http://wakalumibprscoid.local/wp-content/uploads/2026/10/a3c126e6a6a030a2aa906c124ba439cd.jpg\";s:11:\"galeri_foto\";s:0:\"\";s:9:\"deskripsi\";s:353:\"Hunian 1 lantai di pemukiman warga yang tenang, aman, dan bebas banjir di Sawangan, Depok.\r\n\r\nMemiliki 2 Kamar Tidur, 1 Kamar Mandi, Ruang Tamu, Dapur, Teras depan, serta akses jalan lingkungan konblok mobil. Listrik 1.300 VA dan air sumur bor jernih. Lokasi strategis dekat sekolah, masjid, puskesmas, dan 15 menit ke Gerbang Tol Sawangan (Tol Desari).\";s:9:\"tata_cara\";s:275:\"Aset ini berstatus Penjualan Sukarela (AYDA) dengan sertifikat SHM asli bersih tanpa sengketa yang telah diverifikasi notaris bank. Peminat dapat menjadwalkan survei lokasi bersama Tim Remedial BPRS Wakalumi dan dapat diajukan fasilitas KPR Syariah Wakalumi (Akad Murabahah).\";s:16:\"kepatuhan_custom\";s:0:\"\";s:10:\"wa_contact\";s:0:\"\";s:6:\"urutan\";i:2;}i:2;a:22:{s:2:\"id\";s:8:\"lelang_3\";s:4:\"kode\";s:13:\"AYDA-2026-003\";s:5:\"judul\";s:73:\"Gedung Ruko Komersial 5 Lantai Strategis Eks Kantor Lama Wakalumi Ciputat\";s:8:\"kategori\";s:4:\"ruko\";s:6:\"status\";s:8:\"tersedia\";s:11:\"harga_limit\";s:16:\"Rp 2.500.000.000\";s:11:\"nilai_pasar\";s:16:\"Rp 3.300.000.000\";s:12:\"uang_jaminan\";s:14:\"Rp 500.000.000\";s:9:\"legalitas\";s:41:\"SHGB / SHM Asli No. 01892 (Clear & Clean)\";s:10:\"luas_tanah\";s:24:\"145 m² (Lebar Muka 6 m)\";s:13:\"luas_bangunan\";s:24:\"580 m² (5 Lantai Kokoh)\";s:6:\"lokasi\";s:72:\"Jl. Dewi Sartika No. 17-18, Cipayung, Kec. Ciputat (Kawasan Niaga Utama)\";s:4:\"kota\";s:17:\"Tangerang Selatan\";s:14:\"tanggal_lelang\";s:51:\"Terbuka (Penjualan Langsung / Penawaran Resmi Bank)\";s:13:\"tempat_lelang\";s:45:\"Pool Aset Wakalumi & On-Site Property Ciputat\";s:10:\"foto_utama\";s:108:\"http://wakalumibprscoid.local/wp-content/uploads/2026/10/299783409_393569579585345_6889301750136088101_n.jpg\";s:11:\"galeri_foto\";s:280:\"https://images.unsplash.com/photo-1555636222-cae831e670b3?auto=format&fit=crop&w=1200&q=80\r\nhttps://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&w=1200&q=80\r\nhttps://images.unsplash.com/photo-1497215728101-856f4ea42174?auto=format&fit=crop&w=1200&q=80\";s:9:\"deskripsi\";s:632:\"Gedung komersial ruko 5 lantai eks kantor operasional lama perbankan di jantung kawasan niaga Dewi Sartika, Ciputat. Posisi tepat di pinggir jalan raya utama dengan lalu lintas ramai 24 jam dan eksposur brand yang sangat tinggi.\r\n\r\nStruktur bangunan beton bertulang sangat kokoh, layout perkantoran modular, eks ruang teller/banking hall, ruang brankas khasanah besi beton, ruang rapat direksi, kamar mandi di setiap lantai, instalasi genset & listrik 16.500 VA, serta area parkir paving luas. Sangat ideal untuk kantor cabang bank/BPR/koperasi, klinik kesehatan/laboratorium, pusat bimbingan belajar/kampus, maupun kantor korporat.\";s:9:\"tata_cara\";s:295:\"Peminat serius dapat mengajukan Surat Penawaran Harga (SPH) resmi atau menjadwalkan survei fisik gedung dengan menghubungi langsung Tim Penyelamatan & Likuidasi Aset BPRS Wakalumi. Bank menyediakan opsi pembayaran tunai bertahap maupun skema fasilitas Pembiayaan Modal Kerja / Investasi Syariah.\";s:16:\"kepatuhan_custom\";s:0:\"\";s:10:\"wa_contact\";s:0:\"\";s:6:\"urutan\";i:3;}}','auto');
