INSERT INTO `wp_options` VALUES (1778,'options_layanan_items_json','[{\"id\":\"pembayaran-va\",\"title\":\"Pembayaran Angsuran via Virtual Account (VA)\",\"short_title\":\"Pembayaran Virtual Account\",\"badge\":\"Layanan Digital\",\"icon\":\"credit-card\",\"summary\":\"Panduan bayar angsuran via Bank Permata Syariah & seluruh bank lain.\",\"intro\":\"BSW bekerjasama dengan Bank Permata Syariah menyediakan fasilitas Virtual Account (VA) untuk kemudahan pembayaran angsuran pembiayaan Anda dari mana saja, kapan saja, dan melalui kanal perbankan apa pun secara real-time.\",\"partner_bank\":\"Bank Permata Syariah\",\"va_code_prefix\":\"728262\",\"va_format\":\"728262 + Nomor Rekening Tabungan\\/Debitur Wakalumi\",\"va_example\":\"7282621080199999\",\"fee_info\":\"Tagihan nominal angsuran tidak muncul otomatis di layar monitor ATM atau aplikasi M-Banking. Anda wajib memasukkan jumlah saldo transfer secara manual dan menambahkan biaya admin transfer sebesar Rp 3.500 agar angsuran masuk secara utuh ke rekening pembiayaan Anda (Contoh: jika angsuran Rp 1.000.000, maka saldo yang diketik adalah Rp 1.003.500).\",\"param_cards\":[{\"title\":\"Bank Mitra Tujuan\",\"value\":\"Bank Permata Syariah (013)\",\"desc\":\"Pilih Bank Permata \\/ Permata UUS di menu transfer bank Anda\",\"badge\":\"\",\"color\":\"teal\",\"can_copy\":false,\"copy_text\":\"\"},{\"title\":\"Format Nomor VA\",\"value\":\"728262 + No. Rekening\",\"desc\":\"Ketik prefix 728262 dilanjutkan nomor rekening debitur Anda\",\"badge\":\"Kode VA\",\"color\":\"emerald\",\"can_copy\":true,\"copy_text\":\"728262\"},{\"title\":\"Input Nominal Mandiri\",\"value\":\"Tagihan Tidak Otomatis Muncul\",\"desc\":\"Ketik jumlah transfer angsuran Anda secara manual di aplikasi bank\",\"badge\":\"Open Payment\",\"color\":\"amber\",\"can_copy\":false,\"copy_text\":\"\"},{\"title\":\"Biaya Admin Switching\",\"value\":\"Wajib Tambah Rp 3.500\",\"desc\":\"Tambahkan ke saldo transfer agar angsuran pokok masuk utuh\",\"badge\":\"+Rp 3.500\",\"color\":\"sky\",\"can_copy\":false,\"copy_text\":\"\"}],\"show_simulation\":true,\"sim_installment\":\"Rp 1.000.000\",\"sim_fee\":\"Rp 3.500\",\"sim_total\":\"Rp 1.003.500\",\"sim_note\":\"\",\"media_gallery\":[],\"channels\":[{\"name\":\"PermataMobile (Sesama Permata)\",\"badge\":\"Sesama Bank\",\"steps\":[\"Buka aplikasi PermataMobile X di smartphone Anda dan lakukan login.\",\"Pilih menu \\\"Pembayaran Tagihan\\\" lalu pilih kategori \\\"Virtual Account\\\".\",\"Masukkan Nomor Virtual Account Anda: format 728262 diikuti nomor rekening debitur (Contoh: 7282621080199999).\",\"Tekan \\\"Lanjut \\/ OK\\\". Layar akan menampilkan rincian tagihan dan Nama Nasabah. Pastikan nama yang muncul sesuai dengan nama Anda.\",\"Masukkan nominal transfer (pastikan saldo telah ditambahkan Rp 3.500 untuk biaya admin).\",\"Konfirmasi transaksi dengan memasukkan PIN \\/ Mobile PIN Anda hingga struk digital berhasil diterbitkan. Simpan bukti transfer tersebut.\"]},{\"name\":\"Mobile Banking Bank Lain (BCA, Mandiri, BRI, BNI, BSI, dll)\",\"badge\":\"Antar Bank\",\"steps\":[\"Buka aplikasi M-Banking bank yang Anda gunakan (misal: BCA Mobile, Livin by Mandiri, BRImo, BNI Mobile, BSI Mobile, CIMB Octo, dll) dan lakukan login.\",\"Pilih menu \\\"Transfer\\\" lalu pilih \\\"Transfer Antar Bank\\\" \\/ \\\"Transfer ke Bank Lain\\\".\",\"Pilih Bank Tujuan: cari dan pilih \\\"Bank Permata\\\" \\/ \\\"Bank Permata Syariah\\\" \\/ \\\"Permata UUS\\\" (Kode Bank: 013).\",\"Masukkan Nomor Rekening Tujuan dengan Nomor Virtual Account Anda: 728262 dilanjutkan nomor rekening debitur Anda (Contoh: 7282621080199999).\",\"Masukkan nominal pembayaran angsuran (tambahkan Rp 3.500 untuk biaya admin transaksi).\",\"Pada layar konfirmasi transfer, periksa kembali detail nama penerima. Nama Anda\\/Debitur Bank Syariah Wakalumi akan tertera pada kolom penerima tagihan.\",\"Masukkan PIN transaksi M-Banking Anda hingga transaksi dinyatakan BERHASIL. Simpan bukti transaksi digital\\/screenshot sebagai tanda bayar.\"]},{\"name\":\"Mesin ATM (Permata, Bersama, Prima, Alto)\",\"badge\":\"Mesin ATM\",\"steps\":[\"Masukkan kartu ATM dan PIN Anda di mesin ATM Permata atau ATM berlogo ATM Bersama \\/ Prima \\/ Alto.\",\"Jika menggunakan ATM Permata: Pilih \\\"Transaksi Lainnya\\\" > \\\"Pembayaran\\\" > \\\"Virtual Account\\\". Masukkan nomor VA (728262 + No. Rekening).\",\"Jika menggunakan ATM Bank Lain: Pilih \\\"Transaksi Lainnya\\\" > \\\"Transfer\\\" > \\\"Ke Rekening Bank Lain\\\". Masukkan Kode Bank Permata (013) diikuti nomor VA (Contoh: 0137282621080199999).\",\"Masukkan jumlah pembayaran angsuran (tambahkan Rp 3.500 untuk biaya transaksi).\",\"Periksa informasi yang tertera pada layar monitor ATM (Nama Nasabah dan Nominal). Jika sudah sesuai, pilih \\\"Ya \\/ Benar\\\".\",\"Ambil struk bukti transfer fisik dari mesin ATM dan simpan dengan baik.\"]},{\"name\":\"Internet Banking (Web Portal)\",\"badge\":\"Web Portal\",\"steps\":[\"Akses dan login ke portal Internet Banking bank Anda melalui peramban (browser).\",\"Pilih menu \\\"Transfer Dana\\\" > \\\"Transfer ke Rekening Bank Lain\\\".\",\"Tentukan Bank Permata Syariah \\/ Permata UUS sebagai bank tujuan transfer.\",\"Ketikkan nomor Virtual Account: 728262 + Nomor Rekening Debitur Wakalumi.\",\"Isi jumlah nominal angsuran + Rp 3.500.\",\"Lakukan otentikasi menggunakan token \\/ SMS OTP sesuai prosedur bank Anda dan cetak bukti pembayaran.\"]}],\"faqs\":[{\"q\":\"Bagaimana jika nama yang muncul di layar bukan nama saya?\",\"a\":\"Mohon jangan lanjutkan transaksi. Periksa kembali digit nomor rekening yang Anda masukkan setelah kode 728262. Jika nomor sudah benar namun nama tetap tidak sesuai, segera hubungi Customer Service Bank Syariah Wakalumi melalui WhatsApp di nomor resmi kami.\"},{\"q\":\"Berapa lama waktu verifikasi pembayaran angsuran melalui VA?\",\"a\":\"Pembayaran melalui Virtual Account diproses secara otomatis dan real-time oleh sistem perbankan. Namun kami menyarankan melakukan pembayaran pada hari kerja sebelum pukul 15.00 WIB untuk memastikan pencatatan administratif di hari yang sama.\"},{\"q\":\"Mengapa saya perlu menambahkan Rp 3.500 ke saldo transfer?\",\"a\":\"Biaya administrasi kanal switching antar-bank mitra sebesar Rp 3.500 didebet dari total nominal yang Anda kirimkan. Agar angsuran pembiayaan Anda masuk dengan nilai bersih yang tepat sesuai kontrak, saldo transfer wajib ditambahkan Rp 3.500.\"},{\"q\":\"Apakah saya harus mengirimkan bukti transfer ke petugas?\",\"a\":\"Meskipun sistem memverifikasi secara otomatis, kami sangat menyarankan nasabah untuk tetap menyimpan struk\\/screenshot bukti transfer, atau mengirimkannya kepada staf Account Officer (AO) pendamping Anda untuk mempercepat rekonsiliasi berkas.\"}]},{\"id\":\"jemput-setoran\",\"title\":\"Layanan Jemput Setoran (Pick-Up Service)\",\"short_title\":\"Layanan Jemput Setoran\",\"badge\":\"Layanan Lapangan Resmi\",\"icon\":\"truck\",\"summary\":\"Petugas resmi bank menjemput setoran tabungan & angsuran langsung ke lokasi Anda.\",\"intro\":\"Bagi nasabah perorangan, pelaku UMKM, maupun lembaga dengan mobilitas tinggi, BSW menyediakan fasilitas Layanan Jemput Setoran langsung ke toko, kantor, atau rumah Anda secara aman dan tertib administrasi.\",\"partner_bank\":\"Staf Lapangan Resmi BSW\",\"va_code_prefix\":\"\",\"va_format\":\"\",\"va_example\":\"\",\"fee_info\":\"Layanan Jemput Setoran ini bebas biaya administrasi tambahan (100% Bebas Biaya) untuk seluruh wilayah operasional terjangkau kantor pusat dan kantor kas Bank Syariah Wakalumi. Demi kenyamanan dan keamanan transaksi Anda, pastikan petugas yang hadir mengenakan seragam kerja resmi dan tanda pengenal (ID Card) aktif, serta selalu meminta lembar Tanda Terima Setoran Resmi yang telah ditandatangani dan dicap stempel validasi sah.\",\"param_cards\":[{\"title\":\"Biaya Layanan\",\"value\":\"100% Bebas Biaya (Gratis)\",\"desc\":\"Tanpa biaya administrasi tambahan bagi nasabah terdaftar Bank Syariah Wakalumi\",\"badge\":\"Gratis\",\"color\":\"emerald\",\"can_copy\":false,\"copy_text\":\"\"},{\"title\":\"Wilayah Jangkauan\",\"value\":\"Area Kantor Pusat & Kas\",\"desc\":\"Meliputi rute operasional petugas Account Officer di sekitar kantor cabang BSW\",\"badge\":\"Area BSW\",\"color\":\"teal\",\"can_copy\":false,\"copy_text\":\"\"},{\"title\":\"Legalitas Petugas\",\"value\":\"Seragam & ID Card Aktif\",\"desc\":\"Wajib membawa buku tanda terima setoran berstempel validasi sah\",\"badge\":\"Resmi\",\"color\":\"amber\",\"can_copy\":false,\"copy_text\":\"\"},{\"title\":\"Waktu Pembukuan\",\"value\":\"Real-Time Same Day\",\"desc\":\"Dana disetorkan sebelum 14.00 WIB langsung masuk rekening di hari yang sama\",\"badge\":\"Hari Ini\",\"color\":\"sky\",\"can_copy\":false,\"copy_text\":\"\"}],\"show_simulation\":false,\"sim_installment\":\"Rp 1.000.000\",\"sim_fee\":\"Rp 3.500\",\"sim_total\":\"Rp 1.003.500\",\"sim_note\":\"\",\"media_gallery\":[],\"channels\":[{\"name\":\"Alur & Mekanisme Penjemputan\",\"badge\":\"Prosedur\",\"steps\":[\"Hubungi Customer Service atau Account Officer (AO) pendamping Anda minimal 1 hari sebelumnya atau pada pagi hari kerja.\",\"Tentukan nominal setoran tabungan atau angsuran, serta alamat lengkap titik penjemputan.\",\"Petugas resmi Bank Syariah Wakalumi akan mendatangi lokasi Anda sesuai jadwal dengan mengenakan seragam resmi dan tanda pengenal (ID Card) aktif.\",\"Serahkan uang setoran kepada petugas untuk dihitung bersama secara transparan.\",\"Petugas akan menyerahkan Formulir Tanda Terima Setoran Resmi yang telah ditandatangani dan dicap validasi.\",\"Dana akan langsung dibukukan ke rekening tabungan atau kartu angsuran Anda pada hari yang sama.\"]}],\"faqs\":[{\"q\":\"Bagaimana cara memastikan petugas yang datang adalah staf resmi?\",\"a\":\"Setiap petugas resmi Bank Syariah Wakalumi wajib mengenakan seragam kerja resmi, membawa kartu identitas karyawan (ID Card) aktif dengan foto yang jelas, serta membawa buku tanda terima berstempel resmi bank. Anda juga dapat memverifikasi nama petugas melalui nomor WhatsApp resmi bank.\"},{\"q\":\"Berapa batas minimal setoran untuk layanan jemput bola ini?\",\"a\":\"Tidak ada ketentuan batas minimal yang memberatkan. Fasilitas ini disesuaikan dengan kesepakatan jadwal dan rute penjemputan Account Officer di wilayah Anda.\"},{\"q\":\"Kapan dana saya masuk ke rekening tabungan\\/angsuran?\",\"a\":\"Dana yang disetorkan sebelum pukul 14.00 WIB akan dibukukan ke sistem core banking pada hari kerja yang sama. Anda dapat memverifikasi mutasi saldo di buku tabungan atau konfirmasi via CS.\"}]}]','auto');
