INSERT INTO `wp_options` VALUES (2038,'options_kegiatan_list','a:2:{i:0;a:18:{s:2:\"id\";s:16:\"keg_bukber_yatim\";s:5:\"judul\";s:29:\"Buka Puasa Bersama Anak Yatim\";s:8:\"kategori\";s:3:\"csr\";s:10:\"tipe_waktu\";s:10:\"terlaksana\";s:13:\"tanggal_mulai\";s:10:\"2026-03-10\";s:15:\"tanggal_selesai\";s:0:\"\";s:5:\"waktu\";s:17:\"16:30 - 19:00 WIB\";s:6:\"lokasi\";s:27:\"Pamulang, Tangerang Selatan\";s:15:\"lokasi_maps_url\";s:0:\"\";s:18:\"status_pendaftaran\";s:5:\"tutup\";s:16:\"link_pendaftaran\";s:0:\"\";s:9:\"link_text\";s:0:\"\";s:6:\"gambar\";s:90:\"http://wakalumibprscoid.local/wp-content/uploads/2026/10/PXL_20260304_115551874-scaled.jpg\";s:9:\"ringkasan\";s:249:\"Di bulan Ramadan, keluarga besar BSW berbagi kebahagiaan melalui buka puasa bersama anak-anak yatim. Kegiatan ini menjadi wujud kepedulian sosial perusahaan dan kebersamaan di bulan yang penuh berkah. Santunan dan doa bersama turut mengiringi acara.\";s:11:\"isi_lengkap\";s:250:\"Di bulan Ramadan, keluarga besar BSW berbagi kebahagiaan melalui buka puasa bersama anak-anak yatim. Kegiatan ini menjadi wujud kepedulian sosial perusahaan dan kebersamaan di bulan yang penuh berkah. Santunan dan doa bersama turut mengiringi acara. \";s:15:\"dokumentasi_url\";s:0:\"\";s:6:\"status\";s:5:\"aktif\";s:6:\"urutan\";i:1;}i:1;a:18:{s:2:\"id\";s:18:\"keg_takjil_ramadan\";s:5:\"judul\";s:24:\"Pembagian Takjil Ramadan\";s:8:\"kategori\";s:3:\"csr\";s:10:\"tipe_waktu\";s:10:\"terlaksana\";s:13:\"tanggal_mulai\";s:10:\"2026-03-05\";s:15:\"tanggal_selesai\";s:0:\"\";s:5:\"waktu\";s:17:\"17:00 - 18:00 WIB\";s:6:\"lokasi\";s:44:\"Depan kantor pusat operasional BPRS Wakalumi\";s:15:\"lokasi_maps_url\";s:0:\"\";s:18:\"status_pendaftaran\";s:5:\"tutup\";s:16:\"link_pendaftaran\";s:0:\"\";s:9:\"link_text\";s:0:\"\";s:6:\"gambar\";s:91:\"http://wakalumibprscoid.local/wp-content/uploads/2026/10/IMG_0578-scaled-e1792958207539.jpg\";s:9:\"ringkasan\";s:175:\"Tim BSW membagikan takjil kepada masyarakat dan pengguna jalan menjelang waktu berbuka. Kegiatan sederhana ini dilakukan sebagai bagian dari semangat berbagi di bulan Ramadan.\";s:11:\"isi_lengkap\";s:175:\"Tim BSW membagikan takjil kepada masyarakat dan pengguna jalan menjelang waktu berbuka. Kegiatan sederhana ini dilakukan sebagai bagian dari semangat berbagi di bulan Ramadan.\";s:15:\"dokumentasi_url\";s:0:\"\";s:6:\"status\";s:5:\"aktif\";s:6:\"urutan\";i:2;}}','auto');
