INSERT INTO `wp_options` VALUES (2165,'options_literasi_pillars_list','a:3:{i:0;a:6:{s:2:\"id\";s:7:\"pilar_1\";s:5:\"title\";s:19:\"Layanan Jemput Bola\";s:3:\"sub\";s:30:\"Akses Transaksi Bebas Hambatan\";s:4:\"desc\";s:238:\"Petugas operasional dan Account Officer kami mendatangi langsung pedagang pasar tradisional, warung, dan tempat usaha nasabah untuk transaksi setor/tarik tabungan serta verifikasi pembiayaan mikro syariah tanpa mengganggu waktu berdagang.\";s:3:\"tag\";s:13:\"Pasar & Mikro\";s:4:\"icon\";s:5:\"truck\";}i:1;a:6:{s:2:\"id\";s:7:\"pilar_2\";s:5:\"title\";s:24:\"Kemitraan Guru & Sekolah\";s:3:\"sub\";s:32:\"Solusi Finansial Tenaga Pendidik\";s:4:\"desc\";s:196:\"Menyediakan akses layanan simpanan dan pembiayaan syariah bagi para guru dan tenaga kependidikan di sekolah-sekolah, didukung sosialisasi perencanaan keuangan keluarga berakad syariah yang amanah.\";s:3:\"tag\";s:14:\"Guru & Sekolah\";s:4:\"icon\";s:12:\"academic-cap\";}i:2;a:6:{s:2:\"id\";s:7:\"pilar_3\";s:5:\"title\";s:24:\"Dukungan Permodalan UMKM\";s:3:\"sub\";s:29:\"Kemudahan Modal Usaha Syariah\";s:4:\"desc\";s:220:\"Mendukung pertumbuhan usaha mikro, kecil, dan menengah melalui skema pembiayaan modal kerja dan investasi syariah yang mudah, transparan, serta mengedepankan prinsip tolong-menolong (ta\\\\\\\'awun) dan bagi hasil yang adil.\";s:3:\"tag\";s:15:\"Permodalan UMKM\";s:4:\"icon\";s:8:\"sparkles\";}}','auto');
INSERT INTO `wp_options` VALUES (2166,'options_literasi_modules_list','a:6:{i:0;a:8:{s:2:\"id\";s:7:\"modul_1\";s:5:\"judul\";s:33:\"Prinsip Fikih Muamalah Bebas Riba\";s:8:\"kategori\";s:5:\"dasar\";s:9:\"kat_label\";s:0:\"\";s:7:\"sasaran\";s:15:\"Masyarakat Umum\";s:9:\"ringkasan\";s:171:\"Memahami filosofi keadilan ekonomi Islam yang melarang bunga (riba), spekulasi berlebih (maisir), dan ketidakjelasan transaksi (gharar) demi melindungi hak sesama manusia.\";s:11:\"isi_lengkap\";s:739:\"Perbankan syariah berlandaskan pada prinsip keadilan, keterbukaan, dan kemaslahatan bersama sesuai syariat Islam.\r\n\r\nPrinsip Utama yang Ditegakkan:\r\n1. Bebas Riba (Bunga): Keuntungan diperoleh dari transaksi riil jual-beli (margin) atau bagi hasil usaha nyata (nisbah), bukan dari tambahan bunga atas pinjaman uang.\r\n2. Bebas Gharar (Ketidakjelasan): Seluruh akad, biaya, hak, dan kewajiban disepakati transparan di awal tanpa ada klausul tersembunyi.\r\n3. Bebas Maisir (Perjudian/Spekulasi): Dana nasabah tidak dialokasikan untuk aktivitas spekulatif yang merugikan pihak lain.\r\n4. Investasi Halal & Etis: Bank Syariah Wakalumi hanya menyalurkan dana pembiayaan pada sektor usaha halal yang bermanfaat bagi masyarakat dan lingkungan hidup.\";s:6:\"urutan\";i:1;}i:1;a:8:{s:2:\"id\";s:7:\"modul_2\";s:5:\"judul\";s:35:\"Akad Simpanan: Wadiah vs Mudharabah\";s:8:\"kategori\";s:8:\"simpanan\";s:9:\"kat_label\";s:0:\"\";s:7:\"sasaran\";s:14:\"Nasabah & Guru\";s:9:\"ringkasan\";s:149:\"Panduan memilih produk simpanan syariah yang tepat: Akad Wadiah yang aman murni titipan atau Mudharabah dengan nisbah imbal hasil bagi hasil bulanan.\";s:11:\"isi_lengkap\";s:786:\"Dalam perbankan syariah, tabungan dan deposito dikelola dengan akad yang jelas sesuai tujuan nasabah:\r\n\r\n1. Akad Wadiah Yad Dhamanah (Titipan Bergaransi):\r\n- Dana nasabah berstatus titipan yang dijamin keamanannya oleh bank dan dapat diambil sewaktu-waktu.\r\n- Bank dapat memberikan bonus (athaya) sukarela tanpa diperjanjikan di awal.\r\n- Sangat cocok untuk kebutuhan transaksi harian, tabungan pendidikan, atau tabungan kurban.\r\n\r\n2. Akad Mudharabah Mutlaqah (Investasi Bagi Hasil):\r\n- Nasabah bertindak sebagai pemilik dana (Shahibul Mal) dan bank sebagai pengelola dana (Mudharib).\r\n- Keuntungan usaha dibagikan setiap bulan berdasarkan porsi bagi hasil (nisbah) yang disepakati di awal (misal 55% nasabah : 45% bank).\r\n- Sangat cocok untuk Deposito Mudharabah dan tabungan berjangka.\";s:6:\"urutan\";i:2;}i:2;a:8:{s:2:\"id\";s:7:\"modul_3\";s:5:\"judul\";s:41:\"Skema Pembiayaan: Murabahah & Modal Kerja\";s:8:\"kategori\";s:10:\"pembiayaan\";s:9:\"kat_label\";s:0:\"\";s:7:\"sasaran\";s:16:\"Pelaku Wirausaha\";s:9:\"ringkasan\";s:148:\"Bagaimana bank syariah menyalurkan modal usaha tanpa bunga: penetapan harga beli dan margin keuntungan tetap, atau kemitraan usaha murni bagi hasil.\";s:11:\"isi_lengkap\";s:917:\"Penyaluran modal usaha di Bank Syariah Wakalumi tidak menggunakan sistem pinjaman berbunga komersial, melainkan akad-akad kemitraan produktif:\r\n\r\n1. Akad Murabahah (Jual Beli dengan Keuntungan Disepakati):\r\n- Bank membelikan barang kebutuhan usaha/aset yang dibutuhkan nasabah (misal: kendaraan niaga, mesin produksi, renovasi tempat usaha).\r\n- Bank menjual kepada nasabah sebesar harga beli ditambah margin keuntungan yang disepakati bersama. Angsuran bersifat tetap (fixed) hingga lunas tanpa risiko bunga mengambang.\r\n\r\n2. Akad Mudharabah & Musyarakah (Kemitraan Modal & Bagi Hasil):\r\n- Bank menyediakan permodalan untuk proyek usaha produktif nasabah, dan hasil keuntungan dibagi berdasarkan nisbah riil yang disepakati.\r\n\r\n3. Akad Ijarah Multijasa (Sewa Manfaat Jasa):\r\n- Digunakan untuk pembiayaan kebutuhan biaya pendidikan, porsi haji/umroh, atau kebutuhan konsumtif produktif dengan ujrah (biaya jasa) tetap.\";s:6:\"urutan\";i:3;}i:3;a:8:{s:2:\"id\";s:7:\"modul_4\";s:5:\"judul\";s:35:\"Manajemen Finansial & Arus Kas UMKM\";s:8:\"kategori\";s:8:\"keuangan\";s:9:\"kat_label\";s:0:\"\";s:7:\"sasaran\";s:15:\"Pengusaha Kecil\";s:9:\"ringkasan\";s:146:\"Langkah praktis menyusun anggaran darurat, memisahkan kas pribadi dan modal dagang, serta memanfaatkan pembiayaan syariah yang aman dan terencana.\";s:11:\"isi_lengkap\";s:674:\"Pengelolaan keuangan yang sehat merupakan kunci keberhasilan dan keberlanjutan usaha mikro dan kecil.\r\n\r\nPanduan Mengelola Arus Kas Berkah:\r\n1. Pisahkan Rekening Usaha dan Pribadi: Selalu gunakan rekening terpisah agar perputaran laba kotor tidak terpakai untuk belanja konsumtif rumah tangga.\r\n2. Siapkan Pos Dana Cadangan (Dana Darurat): Sisihkan 5-10% dari keuntungan usaha secara berkala ke dalam tabungan syariah berbiaya admin ringan.\r\n3. Rencanakan Kebutuhan Permodalan dengan Tepat: Pilih skema pembiayaan syariah yang sesuai dengan siklus perputaran usaha, seperti akad Murabahah untuk pengadaan barang atau Mudharabah untuk penambahan modal kerja yang berkeadilan.\";s:6:\"urutan\";i:4;}i:4;a:8:{s:2:\"id\";s:7:\"modul_5\";s:5:\"judul\";s:40:\"Waspada Investasi Bodong & Pinjol Ilegal\";s:8:\"kategori\";s:8:\"keamanan\";s:9:\"kat_label\";s:0:\"\";s:7:\"sasaran\";s:15:\"Masyarakat Luas\";s:9:\"ringkasan\";s:138:\"Panduan resmi mengenali modus penipuan berkedok syariah, bahaya pinjol tanpa izin OJK, serta menjaga keamanan data pribadi perbankan Anda.\";s:11:\"isi_lengkap\";s:737:\"Otoritas Jasa Keuangan (OJK) bersama Bank Syariah Wakalumi menghimbau masyarakat untuk selalu menerapkan prinsip 2L sebelum menaruh dana atau mengajukan pembiayaan:\r\n\r\n1. Legal: Periksa apakah lembaga yang menawarkan investasi atau pinjaman telah memiliki izin usaha resmi dan diawasi oleh OJK/Kemenkop.\r\n2. Logis: Waspada terhadap janji keuntungan pasti tanpa risiko dalam waktu singkat. Dalam ekonomi syariah, keuntungan selalu berjalan seiring dengan usaha riil (al-ghunmu bil ghurmi).\r\n\r\nTips Keamanan Data Perbankan:\r\n- Jangan pernah membagikan nomor PIN, password, atau kode OTP kepada siapapun, termasuk oknum yang mengaku petugas bank.\r\n- Selalu verifikasi pesan panggilan atau tawaran pinjaman melalui nomor WhatsApp resmi bank.\";s:6:\"urutan\";i:5;}i:5;a:8:{s:2:\"id\";s:7:\"modul_6\";s:5:\"judul\";s:38:\"Jaminan Simpanan LPS hingga Rp2 Miliar\";s:8:\"kategori\";s:8:\"keamanan\";s:9:\"kat_label\";s:0:\"\";s:7:\"sasaran\";s:16:\"Nasabah Simpanan\";s:9:\"ringkasan\";s:130:\"Simpanan Anda di Bank Syariah Wakalumi aman terlindungi oleh Lembaga Penjamin Simpanan (LPS) dengan memenuhi syarat 3T penjaminan.\";s:11:\"isi_lengkap\";s:614:\"PT BPRS Wakalumi (Bank Syariah Wakalumi) adalah bank peserta penjaminan Lembaga Penjamin Simpanan (LPS).\r\n\r\nKetentuan Penjaminan Simpanan Syariah:\r\n1. Nilai Maksimal Penjaminan: Simpanan nasabah dijamin hingga Rp2.000.000.000 (Dua Miliar Rupiah) per nasabah per bank.\r\n2. Kriteria 3T yang Harus Dipenuhi:\r\n- Tercatat dalam pembukuan bank.\r\n- Tingkat imbal hasil/bagi hasil wajar sesuai ketentuan batas penjaminan yang ditetapkan LPS.\r\n- Tidak melakukan tindakan yang merugikan bank (misal: tidak memiliki kredit macet).\r\n\r\nDengan perlindungan LPS, nasabah dapat menabung dan berdeposito dengan tenang serta berkah.\";s:6:\"urutan\";i:6;}}','auto');
