INSERT INTO `wp_options` VALUES (2233,'options_bm_items_json','[{\"id\":\"tentang-baitul-maal\",\"title\":\"Mengenal Baitul Maal BSW\",\"short_title\":\"Tentang Baitul Maal\",\"badge\":\"Fungsi Sosial Syariah\",\"icon\":\"heart\",\"color\":\"teal\",\"summary\":\"Peran kepedulian sosial, tujuan, sasaran, dan manfaat Baitul Maal.\",\"intro\":\"Dalam sistem perbankan syariah, di samping menjalankan fungsi intermediasi keuangan (Baitul Tamwil), terdapat nilai kepedulian sosial (Baitul Maal) sebagai wujud komitmen terhadap kemaslahatan dan pemberdayaan umat secara berkelanjutan.\",\"main_image\":\"\",\"main_image_caption\":\"\",\"main_quote\":\"\\\"Perumpamaan orang-orang yang menafkahkan hartanya di jalan Allah adalah serupa dengan sebutir benih yang menumbuhkan tujuh bulir, pada tiap-tiap bulir seratus biji. Allah melipatgandakan (ganjaran) bagi siapa yang Dia kehendaki.\\\" (QS. Al-Baqarah: 261)\",\"main_content\":\"Baitul Maal merupakan fungsi pengelolaan dan penyaluran dana sosial keagamaan yang berlandaskan prinsip amanah, transparansi, serta kepatuhan terhadap ketentuan syariah.\\n\\nMelalui fungsi sosial ini, lembaga keuangan syariah berperan sebagai jembatan kebaikan yang menghubungkan kepedulian para dermawan dengan masyarakat yang membutuhkan, guna mendorong terciptanya keseimbangan sosial dan penguatan ekonomi umat di lingkungan sekitar.\",\"show_pillars\":true,\"pillars_section_title\":\"Tujuan, Sasaran & Manfaat Utama\",\"pillars_section_badge\":\"3 Pokok Bahasan\",\"pillar_cards\":[{\"title\":\"Tujuan\",\"badge\":\"Arah & Orientasi\",\"icon\":\"target\",\"color\":\"teal\",\"desc\":\"Menghimpun dan mengelola dana sosial syariah secara amanah, transparan, dan terarah.\\nMenyalurkan manfaat dana kebajikan secara tepat guna sesuai ketentuan syariah.\\nMenumbuhkan semangat kepedulian dan literasi keuangan sosial Islam di tengah masyarakat.\"},{\"title\":\"Sasaran\",\"badge\":\"Penerima Manfaat\",\"icon\":\"users\",\"color\":\"blue\",\"desc\":\"Masyarakat prasejahtera dan golongan penerima manfaat (mustahik) di wilayah sekitar.\\nPelaku usaha mikro dan kecil yang membutuhkan penguatan kapasitas kemandirian.\\nKegiatan sosial, pendidikan, dakwah, serta sarana kemaslahatan umum.\"},{\"title\":\"Manfaat\",\"badge\":\"Dampak Kebaikan\",\"icon\":\"sparkles\",\"color\":\"amber\",\"desc\":\"Menyucikan harta dan menghadirkan keberkahan bagi para penunai dana kebajikan.\\nMeringankan beban kebutuhan dasar sekaligus mendorong kemandirian ekonomi penerima manfaat.\\nMemperkuat ukhuwah dan solidaritas sosial antara lembaga, nasabah, dan masyarakat.\"}],\"show_zakat\":false,\"zakat_color\":\"teal\",\"zakat_icon\":\"scale\",\"zakat_badge\":\"Prinsip & Ketentuan\",\"zakat_title\":\"\",\"zakat_desc\":\"\",\"zakat_quote\":\"\",\"zakat_asnaf_title\":\"\",\"zakat_asnaf_subtitle\":\"\",\"zakat_asnaf_list\":[],\"zakat_syarat_title\":\"\",\"zakat_syarat_subtitle\":\"\",\"zakat_syarat_list\":[],\"show_sedekah\":false,\"sedekah_color\":\"amber\",\"sedekah_icon\":\"hand-heart\",\"sedekah_badge\":\"\",\"sedekah_title\":\"\",\"sedekah_image\":\"\",\"sedekah_desc\":\"\",\"sedekah_quote\":\"\",\"sedekah_points_title\":\"\",\"sedekah_points\":[],\"show_wakaf\":false,\"wakaf_color\":\"indigo\",\"wakaf_icon\":\"building\",\"wakaf_badge\":\"\",\"wakaf_title\":\"\",\"wakaf_desc\":\"\",\"wakaf_quote\":\"\",\"wakaf_keunggulan_title\":\"\",\"wakaf_keunggulan_list\":[],\"wakaf_program_title\":\"\",\"wakaf_program_list\":[],\"custom_sections\":[],\"show_gallery\":false,\"gallery_title\":\"Dokumentasi & Infografis Sosial\",\"media_gallery\":[],\"show_faqs\":true,\"faq_section_title\":\"Tanya Jawab Seputar Baitul Maal\",\"faqs\":[{\"q\":\"Apa perbedaan antara fungsi Baitul Maal dan Baitul Tamwil?\",\"a\":\"Baitul Tamwil berfokus pada kegiatan layanan intermediasi keuangan dan perbankan syariah yang bersifat komersial\\/produktif (seperti tabungan, deposito, dan pembiayaan sesuai akad syariah). Sedangkan Baitul Maal berfokus pada pengelolaan serta penyaluran dana sosial dan kebajikan umat yang bersifat nirlaba untuk kemaslahatan masyarakat.\"},{\"q\":\"Bagaimana prinsip pengelolaan dana sosial pada Baitul Maal?\",\"a\":\"Pengelolaan dana sosial berpedoman pada prinsip kepatuhan syariah, amanah, pencatatan yang terpisah dari dana operasional komersial, serta penyaluran yang tepat sasaran kepada golongan yang berhak menerima.\"}]},{\"id\":\"program-sosial-kemaslahatan\",\"title\":\"Ruang Lingkup Kegiatan Sosial & Kemaslahatan Umat\",\"short_title\":\"Program & Kemaslahatan\",\"badge\":\"Aksi & Kepedulian Sosial\",\"icon\":\"hand-heart\",\"color\":\"blue\",\"summary\":\"Fokus kepedulian sosial, santunan, pendidikan, dan pemberdayaan masyarakat.\",\"intro\":\"Kegiatan Baitul Maal tidak hanya terbatas pada edukasi zakat semata, melainkan mencakup berbagai bentuk kepedulian sosial, santunan kemanusiaan, dukungan literasi pendidikan, serta penguatan kapasitas usaha mikro di lingkungan masyarakat.\",\"main_image\":\"\",\"main_image_caption\":\"\",\"main_quote\":\"\\\"Sebaik-baik manusia adalah yang paling bermanfaat bagi manusia lainnya.\\\" (HR. Ahmad & Thabrani)\",\"main_content\":\"Sebagai bagian dari ekosistem keuangan syariah yang dekat dengan masyarakat, Baitul Maal BSW berupaya menghadirkan manfaat nyata melalui program-program sosial yang adaptif, kolaboratif, dan berkelanjutan.\\n\\nSetiap inisiatif dirancang agar memberikan dampak positif baik secara langsung (karitatif\\/santunan) maupun jangka panjang (pemberdayaan dan literasi).\",\"show_pillars\":true,\"pillars_section_title\":\"Bidang Fokus Kepedulian & Kemaslahatan\",\"pillars_section_badge\":\"4 Fokus Utama\",\"pillar_cards\":[{\"title\":\"Sosial & Kemanusiaan\",\"badge\":\"Santunan & Kepedulian\",\"icon\":\"hand-heart\",\"color\":\"emerald\",\"desc\":\"Santunan anak yatim dan masyarakat dhuafa di sekitar wilayah operasional.\\nKegiatan berbagi berkah Ramadan seperti buka puasa bersama dan pembagian takjil.\\nBantuan tanggap kepedulian bagi warga yang terdampak musibah.\"},{\"title\":\"Pendidikan & Literasi\",\"badge\":\"Edukasi Syariah\",\"icon\":\"academic-cap\",\"color\":\"blue\",\"desc\":\"Sosialisasi dan edukasi literasi keuangan syariah bagi pelajar, guru, dan masyarakat.\\nDukungan sarana penunjang pendidikan dan kegiatan keislaman.\\nPeningkatan kesadaran pengelolaan keuangan keluarga yang sehat dan berkah.\"},{\"title\":\"Pemberdayaan Ekonomi\",\"badge\":\"Kemandirian Umat\",\"icon\":\"briefcase\",\"color\":\"amber\",\"desc\":\"Pendampingan dan penguatan kapasitas pelaku usaha mikro dan pedagang kecil.\\nMendorong budaya menabung dan pengelolaan usaha sesuai prinsip syariah.\\nSinergi pemberdayaan komunitas ekonomi lokal agar lebih mandiri.\"},{\"title\":\"Kemaslahatan Umum\",\"badge\":\"Sarana Ibadah & Komunitas\",\"icon\":\"building\",\"color\":\"purple\",\"desc\":\"Dukungan pemeliharaan sarana ibadah (masjid\\/mushalla) dan kegiatan dakwah.\\nPartisipasi aktif dalam kegiatan sosial kemasyarakatan di lingkungan sekitar kantor.\\nMempererat silaturahmi antara insan perbankan syariah dan tokoh masyarakat.\"}],\"show_zakat\":false,\"zakat_color\":\"teal\",\"zakat_icon\":\"scale\",\"zakat_badge\":\"\",\"zakat_title\":\"\",\"zakat_desc\":\"\",\"zakat_quote\":\"\",\"zakat_asnaf_title\":\"\",\"zakat_asnaf_subtitle\":\"\",\"zakat_asnaf_list\":[],\"zakat_syarat_title\":\"\",\"zakat_syarat_subtitle\":\"\",\"zakat_syarat_list\":[],\"show_sedekah\":false,\"sedekah_color\":\"amber\",\"sedekah_icon\":\"hand-heart\",\"sedekah_badge\":\"\",\"sedekah_title\":\"\",\"sedekah_image\":\"\",\"sedekah_desc\":\"\",\"sedekah_quote\":\"\",\"sedekah_points_title\":\"\",\"sedekah_points\":[],\"show_wakaf\":true,\"wakaf_color\":\"indigo\",\"wakaf_icon\":\"shield-check\",\"wakaf_badge\":\"Tata Kelola Sosial Syariah\",\"wakaf_title\":\"Prinsip Pengelolaan & Sinergi Kemaslahatan\",\"wakaf_desc\":\"Setiap kegiatan sosial dan penyaluran dana kebajikan dilaksanakan dengan mengedepankan prinsip kehati-hatian, tepat sasaran, serta selaras dengan nilai-nilai syariah.\",\"wakaf_quote\":\"\",\"wakaf_keunggulan_title\":\"Prinsip Tata Kelola Sosial\",\"wakaf_keunggulan_list\":[\"Kepatuhan Syariah | Seluruh penyaluran dana sosial dipastikan sesuai dengan ketentuan dan fatwa syariah.\",\"Amanah & Akuntabel | Pencatatan dana sosial dikelola secara tertib, transparan, dan dapat dipertanggungjawabkan.\",\"Tepat Sasaran | Mengutamakan penerima manfaat di lingkungan sekitar yang benar-benar membutuhkan.\",\"Keberlanjutan Manfaat | Mendorong program yang memberi nilai tambah jangka panjang bagi masyarakat.\"],\"wakaf_program_title\":\"Bentuk Kegiatan & Kolaborasi\",\"wakaf_program_list\":[\"Kegiatan Sosial Berkala | Penyelenggaraan agenda kepedulian pada momen hari besar Islam dan bulan suci Ramadan.\",\"Sinergi Lembaga & Komunitas | Kolaborasi bersama pengurus masjid, sekolah, dan komunitas masyarakat setempat.\",\"Edukasi & Literasi Terpadu | Penyuluhan keuangan syariah dan pengenalan instrumen dana kebajikan Islam.\",\"Pelayanan Ramah & Terbuka | Membuka ruang komunikasi bagi masyarakat yang ingin bersinergi dalam kebaikan.\"],\"custom_sections\":[],\"show_gallery\":false,\"gallery_title\":\"Dokumentasi Kegiatan Sosial\",\"media_gallery\":[],\"show_faqs\":false,\"faq_section_title\":\"Tanya Jawab Seputar Program Sosial\",\"faqs\":[]},{\"id\":\"informasi-ziswaf\",\"title\":\"Mengenal ZISWAF (Zakat, Infak, Sedekah & Wakaf)\",\"short_title\":\"Edukasi ZISWAF\",\"badge\":\"Literasi Filantropi Islam\",\"icon\":\"sparkles\",\"color\":\"amber\",\"summary\":\"Panduan lengkap mengenai zakat, penerima & syarat wajib, infak, sedekah, serta wakaf.\",\"intro\":\"ZISWAF (Zakat, Infak, Sedekah, dan Wakaf) merupakan instrumen keuangan sosial Islam yang memiliki peran strategis dalam menyucikan harta, mempererat solidaritas sosial, serta membangun kemandirian ekonomi umat secara berkesinambungan.\",\"main_image\":\"\",\"main_image_caption\":\"\",\"main_quote\":\"\\\"Ambillah zakat dari sebagian harta mereka, dengan zakat itu kamu membersihkan dan mensucikan mereka dan mendoalah untuk mereka. Sesungguhnya doa kamu itu (menjadi) ketenteraman jiwa bagi mereka.\\\" (QS. At-Taubah: 103)\",\"main_content\":\"Dalam syariat Islam, setiap harta yang dimiliki seorang Muslim mengandung hak bagi saudara-saudara lainnya yang membutuhkan. Penunaian Zakat sebagai kewajiban rukun Islam, serta pengamalan Infak, Sedekah, dan Wakaf sebagai amal kebajikan utama, menjadi wujud syukur atas nikmat rezeki sekaligus sarana meraih keberkahan harta yang bersih dan produktif.\",\"show_pillars\":false,\"pillars_section_title\":\"Tujuan, Sasaran & Manfaat\",\"pillars_section_badge\":\"3 Pokok Bahasan\",\"pillar_cards\":[],\"show_zakat\":true,\"zakat_color\":\"teal\",\"zakat_icon\":\"scale\",\"zakat_badge\":\"Rukun Islam & Penyucian Harta\",\"zakat_title\":\"Ketentuan Umum Zakat\",\"zakat_desc\":\"Zakat adalah bagian tertentu dari harta yang wajib dikeluarkan oleh setiap Muslim apabila telah mencapai syarat yang ditetapkan (nisab dan haul) untuk diserahkan kepada golongan yang berhak menerimanya (mustahik) sesuai ketentuan syariat Islam.\",\"zakat_quote\":\"\\\"Dan dirikanlah shalat, tunaikanlah zakat dan ruku\'lah beserta orang-orang yang ruku\'.\\\" (QS. Al-Baqarah: 43)\",\"zakat_asnaf_title\":\"Golongan Penerima Zakat (8 Asnaf)\",\"zakat_asnaf_subtitle\":\"Delapan golongan yang berhak menerima penyaluran zakat sesuai QS. At-Taubah ayat 60:\",\"zakat_asnaf_list\":[\"Fakir | Orang yang hampir tidak memiliki sesuatu sehingga tidak mampu memenuhi kebutuhan pokok hidupnya.\",\"Miskin | Orang yang memiliki harta atau penghasilan, namun belum mencukupi kebutuhan dasar untuk dirinya dan tanggungannya.\",\"Amil | Pihak yang bertugas menghimpun, mengelola, menjaga, dan menyalurkan dana zakat secara amanah.\",\"Muallaf | Orang yang baru memeluk agama Islam dan membutuhkan penguatan keimanan serta dukungan sosial.\",\"Riqab | Hamba sahaya atau upaya membebaskan umat dari belenggu perbudakan dan penindasan.\",\"Gharimin | Orang yang terlilit utang untuk memenuhi kebutuhan hidup yang halal dan tidak sanggup melunasinya.\",\"Fi Sabilillah | Orang atau kegiatan yang berjuang di jalan Allah demi kemaslahatan, dakwah, dan pendidikan umat.\",\"Ibnu Sabil | Musafir yang sedang dalam perjalanan bukan untuk maksiat dan kehabisan bekal di perjalanan.\"],\"zakat_syarat_title\":\"Syarat Wajib Zakat\",\"zakat_syarat_subtitle\":\"Ketentuan pokok yang menjadikan harta seorang Muslim wajib dizakati:\",\"zakat_syarat_list\":[\"Beragama Islam | Kewajiban zakat berlaku khusus bagi setiap individu Muslim.\",\"Merdeka | Memiliki kebebasan penuh sebagai individu yang merdeka dalam mengelola hartanya.\",\"Kepemilikan Penuh & Halal | Harta diperoleh dengan cara yang halal dan berada dalam penguasaan penuh pemiliknya.\",\"Melampaui Kebutuhan Pokok | Harta tersebut merupakan kelebihan dari kebutuhan dasar hidup diri dan keluarga yang ditanggung.\",\"Mencapai Nisab | Jumlah harta telah mencapai batas minimal wajib zakat sesuai jenis hartanya (misal setara 85 gram emas untuk zakat maal).\",\"Mencapai Haul | Harta telah dimiliki selama genap 1 tahun hijriah (12 bulan qamariyah) untuk jenis harta yang mensyaratkan haul.\"],\"show_sedekah\":true,\"sedekah_color\":\"amber\",\"sedekah_icon\":\"hand-heart\",\"sedekah_badge\":\"Amal Kebajikan Setiap Waktu\",\"sedekah_title\":\"Keutamaan Infak & Sedekah\",\"sedekah_image\":\"\",\"sedekah_desc\":\"Berbeda dengan zakat yang memiliki batasan nisab dan haul, Infak dan Sedekah bersifat fleksibel serta dapat ditunaikan kapan saja dan dalam jumlah berapa saja. Infak berkaitan dengan pengeluaran harta untuk kebaikan, sedangkan sedekah mencakup segala bentuk kebaikan baik materi maupun non-materi.\",\"sedekah_quote\":\"\\\"Sedekah itu tidaklah mengurangi harta, dan tidaklah Allah menambah bagi seorang hamba yang pemaaf kecuali kemuliaan.\\\" (HR. Muslim)\",\"sedekah_points_title\":\"Hikmah & Keutamaan Infak serta Sedekah\",\"sedekah_points\":[\"Menyucikan Jiwa & Harta | Menumbuhkan sifat dermawan, rasa syukur, dan menjauhkan hati dari sifat kikir.\",\"Melipatgandakan Keberkahan Rezeki | Membuka pintu keberkahan dalam usaha, pekerjaan, dan kehidupan keluarga.\",\"Meringankan Beban Sesama | Membantu pemenuhan kebutuhan masyarakat prasejahtera, yatim, dan dhuafa secara langsung.\",\"Naungan di Hari Akhir | Menjadi amal kebajikan yang menaungi dan menyelamatkan seorang mukmin di hari perhitungan.\"],\"show_wakaf\":true,\"wakaf_color\":\"indigo\",\"wakaf_icon\":\"building\",\"wakaf_badge\":\"Amal Jariyah Abadi\",\"wakaf_title\":\"Mengenal Wakaf & Wakaf Uang\",\"wakaf_desc\":\"Wakaf adalah perbuatan hukum wakif (pihak yang mewakafkan) untuk memisahkan dan\\/atau menyerahkan sebagian harta benda miliknya guna dimanfaatkan selamanya atau untuk jangka waktu tertentu sesuai dengan kepentingannya bagi keperluan ibadah dan\\/atau kesejahteraan umum menurut syariah.\",\"wakaf_quote\":\"\\\"Apabila manusia meninggal dunia, maka terputuslah amalnya kecuali dari tiga perkara: sedekah jariyah (wakaf), ilmu yang bermanfaat, atau anak shalih yang mendoakannya.\\\" (HR. Muslim)\",\"wakaf_keunggulan_title\":\"Keunggulan Wakaf\",\"wakaf_keunggulan_list\":[\"Pokok Harta Terjaga Utuh | Nilai pokok aset atau dana wakaf dijaga kelestariannya dan tidak boleh berkurang.\",\"Pahala Jariyah Berkelanjutan | Manfaat hasil pengelolaan wakaf terus mengalirkan pahala meskipun wakif telah wafat.\",\"Inklusif & Terjangkau | Melalui instrumen wakaf uang, masyarakat dapat berwakaf dengan nominal yang terjangkau.\",\"Berdampak Jangka Panjang | Mendukung pembangunan infrastruktur sosial dan pemberdayaan ekonomi lintas generasi.\"],\"wakaf_program_title\":\"Ruang Lingkup Pemanfaatan Wakaf\",\"wakaf_program_list\":[\"Sarana Ibadah & Keagamaan | Dukungan pembangunan dan pemeliharaan masjid, mushalla, serta fasilitas dakwah.\",\"Pendidikan & Literasi Umat | Penyediaan sarana pendidikan, pesantren, beasiswa, dan peningkatan kualitas SDM.\",\"Kesehatan & Sosial Masyarakat | Dukungan layanan kesehatan, santunan sosial, dan fasilitas kemaslahatan umum.\",\"Pemberdayaan Ekonomi Produktif | Pengelolaan aset produktif berbasis syariah yang hasilnya disalurkan bagi kesejahteraan penerima manfaat.\"],\"custom_sections\":[],\"show_gallery\":false,\"gallery_title\":\"Infografis Edukasi ZISWAF\",\"media_gallery\":[],\"show_faqs\":true,\"faq_section_title\":\"Tanya Jawab Seputar Edukasi ZISWAF\",\"faqs\":[{\"q\":\"Apa perbedaan utama antara Zakat, Infak, Sedekah, dan Wakaf?\",\"a\":\"Zakat hukumnya wajib bagi Muslim yang hartanya telah mencapai batas nisab dan haul, serta disalurkan khusus kepada 8 golongan asnaf. Infak dan Sedekah hukumnya sunnah (anjuran mulia) tanpa batas minimal nominal maupun waktu. Sedangkan Wakaf adalah penyerahan harta yang nilai pokoknya dijaga tetap utuh (tidak habis dikonsumsi), sementara hasil manfaatnya disalurkan secara berkelanjutan untuk kemaslahatan umat.\"},{\"q\":\"Mengapa zakat perlu memperhatikan syarat nisab dan haul?\",\"a\":\"Nisab adalah batas minimal jumlah harta yang dimiliki, sedangkan haul adalah batas waktu kepemilikan harta selama 1 tahun hijriah. Kedua syarat ini menunjukkan keadilan syariat Islam, di mana kewajiban zakat hanya dibebankan kepada mereka yang telah berkecukupan melebihi kebutuhan pokoknya.\"}]}]','auto');
