INSERT INTO `wp_options` VALUES (2452,'options_pengaduan_channels','a:2:{i:0;a:15:{s:5:\"title\";s:26:\"Pengaduan Langsung ke Bank\";s:5:\"badge\";s:27:\"Tahap 1: Saluran Resmi Bank\";s:3:\"tag\";s:25:\"Bebas Biaya (100% Gratis)\";s:5:\"color\";s:7:\"emerald\";s:4:\"desc\";s:237:\"Sampaikan keluhan transaksi, rekening, pembiayaan, atau pelayanan secara langsung. Tim Penanganan Pengaduan dan Customer Care Bank Syariah Wakalumi siap menyelesaikan secara seksama dan profesional berpedoman pada POJK No. 22 Tahun 2023.\";s:10:\"status_tag\";s:18:\"Chat & Loket Aktif\";s:10:\"contact_wa\";s:13:\"6281517380388\";s:13:\"contact_phone\";s:13:\"(021) 7401667\";s:13:\"contact_email\";s:28:\"pengaduan@wakalumibprs.co.id\";s:12:\"contact_desc\";s:56:\"Kantor Pusat & Seluruh Jaringan Kantor Kas BPRS Wakalumi\";s:16:\"btn_primary_text\";s:22:\"Kirim Pengaduan via WA\";s:15:\"btn_primary_url\";s:0:\"\";s:18:\"btn_secondary_text\";s:17:\"Kirim Email Resmi\";s:17:\"btn_secondary_url\";s:0:\"\";s:6:\"urutan\";i:1;}i:1;a:15:{s:5:\"title\";s:25:\"Eskalasi Pengaduan ke OJK\";s:5:\"badge\";s:27:\"Tahap 2: Eskalasi Regulator\";s:3:\"tag\";s:26:\"Jika Belum Ada Kesepakatan\";s:5:\"color\";s:3:\"red\";s:4:\"desc\";s:226:\"Sesuai regulasi POJK, jika proses penanganan di bank belum mencapai kesepakatan atau tidak ditindaklanjuti dalam batas waktu SLA (20 hari kerja), nasabah berhak mengeskalasikan pengaduan ke portal resmi APPK OJK atau LAPS SJK.\";s:10:\"status_tag\";s:22:\"Portal Regulator Resmi\";s:10:\"contact_wa\";s:0:\"\";s:13:\"contact_phone\";s:3:\"157\";s:13:\"contact_email\";s:0:\"\";s:12:\"contact_desc\";s:57:\"Portal APPK: kontak157.ojk.go.id • Sengketa: lapssjk.id\";s:16:\"btn_primary_text\";s:20:\"Buka Portal APPK OJK\";s:15:\"btn_primary_url\";s:27:\"https://kontak157.ojk.go.id\";s:18:\"btn_secondary_text\";s:17:\"Kunjungi LAPS SJK\";s:17:\"btn_secondary_url\";s:18:\"https://lapssjk.id\";s:6:\"urutan\";i:2;}}','auto');
