INSERT INTO `wp_options` VALUES (2456,'options_pengaduan_steps','a:4:{i:0;a:8:{s:6:\"number\";s:2:\"01\";s:5:\"badge\";s:12:\"Langkah Awal\";s:5:\"title\";s:30:\"Penyampaian & Registrasi Aduan\";s:4:\"desc\";s:142:\"Nasabah menyampaikan pengaduan kepada bank melalui WhatsApp resmi, telepon hotline, kantor kas, atau email disertai bukti pendukung transaksi.\";s:6:\"output\";s:43:\"Output: Nomor Registrasi Tanda Terima Aduan\";s:5:\"image\";s:0:\"\";s:7:\"caption\";s:0:\"\";s:6:\"urutan\";i:1;}i:1;a:8:{s:6:\"number\";s:2:\"02\";s:5:\"badge\";s:13:\"Langkah Kedua\";s:5:\"title\";s:28:\"Verifikasi & Validasi Berkas\";s:4:\"desc\";s:125:\"Petugas bank memverifikasi identitas nasabah, mencocokkan kronologis, serta memastikan kelengkapan dokumen persyaratan aduan.\";s:6:\"output\";s:40:\"Output: Berita Acara & Checklist Dokumen\";s:5:\"image\";s:0:\"\";s:7:\"caption\";s:0:\"\";s:6:\"urutan\";i:2;}i:2;a:8:{s:6:\"number\";s:2:\"03\";s:5:\"badge\";s:14:\"Langkah Ketiga\";s:5:\"title\";s:27:\"Investigasi & Analisis Bank\";s:4:\"desc\";s:148:\"Pemeriksaan catatan sistem perbankan syariah secara komprehensif, konfirmasi organ terkait, dan perumusan solusi berkeadilan dalam jangka waktu SLA.\";s:6:\"output\";s:44:\"Output: Kajian Solusi Sesuai Prinsip Syariah\";s:5:\"image\";s:0:\"\";s:7:\"caption\";s:0:\"\";s:6:\"urutan\";i:3;}i:3;a:8:{s:6:\"number\";s:2:\"04\";s:5:\"badge\";s:13:\"Langkah Akhir\";s:5:\"title\";s:31:\"Tanggapan Resmi & Opsi Eskalasi\";s:4:\"desc\";s:150:\"Penyampaian tanggapan resmi bank maksimal 20 hari kerja. Jika belum tercapai mufakat, nasabah dapat mengeskalasikan ke OJK (Kontak 157) atau LAPS SJK.\";s:6:\"output\";s:44:\"Output: Surat Tanggapan Resmi / Eskalasi OJK\";s:5:\"image\";s:0:\"\";s:7:\"caption\";s:0:\"\";s:6:\"urutan\";i:4;}}','auto');
