INSERT INTO `wp_options` VALUES (2603,'options_karir_badge','Peluang Karir & Rekrutmen Resmi','auto');
INSERT INTO `wp_options` VALUES (2604,'options_karir_title','Tumbuh & Berkarya Bersama Bank Syariah Wakalumi','auto');
INSERT INTO `wp_options` VALUES (2605,'options_karir_desc','Bergabunglah bersama insan perbankan syariah yang amanah, berintegritas tinggi, dan berorientasi pada kemajuan ekonomi umat. Temukan peluang karir terbaik yang selaras dengan potensi dan nilai-nilai kebaikan Anda.','auto');
INSERT INTO `wp_options` VALUES (2606,'options_karir_fraud_badge','Himbauan Resmi Bebas Biaya','auto');
INSERT INTO `wp_options` VALUES (2607,'options_karir_fraud_title','Waspada Penipuan Mengatasnamakan Rekrutmen BSW','auto');
INSERT INTO `wp_options` VALUES (2608,'options_karir_fraud_desc','PT BPRS Wakalumi (Bank Syariah Wakalumi) TIDAK PERNAH memungut biaya apapun (termasuk biaya transportasi, akomodasi, maupun biaya administrasi berkas) dalam seluruh tahapan seleksi penerimaan karyawan. Undangan resmi selalu disampaikan melalui saluran email resmi bank atau nomor kontak resmi Divisi Personalia. Waspadai segala bentuk penipuan yang mengatasnamakan Bank Syariah Wakalumi.','auto');
INSERT INTO `wp_options` VALUES (2609,'options_karir_values_badge','Budaya Perusahaan','auto');
INSERT INTO `wp_options` VALUES (2610,'options_karir_values_title','Mengapa Membangun Karir Bersama Bank Syariah Wakalumi?','auto');
INSERT INTO `wp_options` VALUES (2611,'options_karir_values_desc','Kami meyakini bahwa keberkahan dan keberlanjutan bank bermula dari lingkungan kerja yang sehat, saling menghargai, dan menjunjung tinggi amanah syariat Islam.','auto');
INSERT INTO `wp_options` VALUES (2612,'options_karir_values_list','a:4:{i:0;a:4:{s:5:\"title\";s:24:\"Prinsip Muamalah Syariah\";s:4:\"desc\";s:141:\"Bekerja dalam ekosistem perbankan yang berlandaskan syariat Islam, bebas riba, serta mengedepankan kehalalan dan keadilan transaksi muamalah.\";s:5:\"color\";s:7:\"emerald\";s:4:\"icon\";s:6:\"shield\";}i:1;a:4:{s:5:\"title\";s:30:\"Pengembangan Potensi Insan BSW\";s:4:\"desc\";s:135:\"Dukungan berkelanjutan untuk mengasah keahlian dan wawasan perbankan syariah melalui bimbingan kerja profesional dan penugasan terarah.\";s:5:\"color\";s:4:\"cyan\";s:4:\"icon\";s:11:\"trending-up\";}i:2;a:4:{s:5:\"title\";s:27:\"Budaya Kolaboratif & ISHLAH\";s:4:\"desc\";s:123:\"Lingkungan kerja yang rukun, saling menghormati, transparan, dan menjunjung tinggi amanah serta etika perbankan yang sehat.\";s:5:\"color\";s:6:\"purple\";s:4:\"icon\";s:5:\"users\";}i:3;a:4:{s:5:\"title\";s:28:\"Kesejahteraan & Keseimbangan\";s:4:\"desc\";s:140:\"Paket remunerasi yang kompetitif, perlindungan kesejahteraan, serta perhatian penuh pada keseimbangan antara produktivitas kerja dan ibadah.\";s:5:\"color\";s:5:\"amber\";s:4:\"icon\";s:5:\"heart\";}}','auto');
INSERT INTO `wp_options` VALUES (2613,'options_karir_stages_badge','Tahapan Seleksi Resmi','auto');
INSERT INTO `wp_options` VALUES (2614,'options_karir_stages_title','Alur Perekrutan Insan Bank Syariah Wakalumi','auto');
INSERT INTO `wp_options` VALUES (2615,'options_karir_stages_desc','Proses seleksi penerimaan karyawan di Bank Syariah Wakalumi dilaksanakan secara terstruktur, objektif, dan transparan melalui 4 tahapan utama:','auto');
INSERT INTO `wp_options` VALUES (2616,'options_karir_stages_list','a:4:{i:0;a:4:{s:4:\"step\";s:2:\"01\";s:5:\"title\";s:32:\"Pengiriman Berkas & Data Pelamar\";s:4:\"desc\";s:143:\"Pelamar mengisi formulir pendaftaran daring resmi dan melampirkan berkas Curriculum Vitae (CV) terbaru sesuai kualifikasi posisi yang diminati.\";s:5:\"color\";s:4:\"cyan\";}i:1;a:4:{s:4:\"step\";s:2:\"02\";s:5:\"title\";s:36:\"Seleksi Berkas & Panggilan Interview\";s:4:\"desc\";s:140:\"Tim Personalia BSW melakukan verifikasi dan seleksi administratif. Pelamar yang memenuhi syarat akan dihubungi untuk jadwal wawancara resmi.\";s:5:\"color\";s:4:\"teal\";}i:2;a:4:{s:4:\"step\";s:2:\"03\";s:5:\"title\";s:26:\"Sesi Wawancara (Interview)\";s:4:\"desc\";s:161:\"Wawancara mendalam mencakup kompetensi teknis, kecocokan profil kerja, dan keselarasan integritas syariah bersama tim Personalia dan Pimpinan Unit kerja terkait.\";s:5:\"color\";s:5:\"amber\";}i:3;a:4:{s:4:\"step\";s:2:\"04\";s:5:\"title\";s:28:\"Penawaran Kerja & Onboarding\";s:4:\"desc\";s:150:\"Kandidat terpilih menerima surat penawaran kerja resmi (Offering Letter) dan arahan persiapan sebelum memulai orientasi kerja resmi sebagai insan BSW.\";s:5:\"color\";s:6:\"purple\";}}','auto');
INSERT INTO `wp_options` VALUES (2617,'options_karir_empty_badge','Status Formasi: Belum Ada Pembukaan Rekrutmen Aktif','auto');
INSERT INTO `wp_options` VALUES (2618,'options_karir_empty_title','Terima Kasih Atas Ketertarikan Anda Berkarya Bersama BSW','auto');
INSERT INTO `wp_options` VALUES (2619,'options_karir_empty_desc','Saat ini seluruh formasi penempatan kerja insan perbankan syariah di lingkungan Bank Syariah Wakalumi telah terisi penuh. Pembukaan gelombang rekrutmen formasi baru berikutnya akan selalu diumumkan secara transparan melalui portal resmi ini dan saluran media sosial resmi bank.','auto');
INSERT INTO `wp_options` VALUES (2620,'options_karir_empty_subcards','a:3:{i:0;a:4:{s:5:\"title\";s:16:\"100% Bebas Biaya\";s:4:\"desc\";s:74:\"Seluruh proses seleksi dan pendaftaran tidak pernah dipungut biaya apapun.\";s:5:\"color\";s:7:\"emerald\";s:4:\"icon\";s:6:\"shield\";}i:1;a:4:{s:5:\"title\";s:18:\"Kanal Resmi Daring\";s:4:\"desc\";s:69:\"Formulir pendaftaran resmi selalu menggunakan tautan Google Form BSW.\";s:5:\"color\";s:4:\"cyan\";s:4:\"icon\";s:5:\"globe\";}i:2;a:4:{s:5:\"title\";s:17:\"Kenali Budaya BSW\";s:4:\"desc\";s:66:\"Kenali profil kepengurusan dan jajaran karyawan bank syariah kami.\";s:5:\"color\";s:5:\"amber\";s:4:\"icon\";s:5:\"users\";}}','auto');
