INSERT INTO `wp_options` VALUES (2624,'options_karir_cta_desc','Tim Personalia / Human Capital kami siap membantu memberikan informasi terkait jadwal seleksi, kualifikasi posisi, serta peluang kemitraan magang mahasiswa.','auto');
