INSERT INTO `wp_posts` VALUES (159,1,'2026-10-26 00:11:34','2026-10-25 17:11:34','','LOGO BSW BARU (modified bprs) putih','','inherit','open','closed','','logo-bsw-baru-modified-bprs-putih','','','2026-10-26 00:11:34','2026-10-25 17:11:34','',0,'http://wakalumibprscoid.local/wp-content/uploads/2026/10/LOGO-BSW-BARU-modified-bprs-putih.png',0,'attachment','image/png',0);
INSERT INTO `wp_posts` VALUES (160,0,'2026-09-25 02:48:01','2026-09-25 02:30:00','<strong>TANGERANG SELATAN</strong> — Bank Syariah Wakalumi (BSW) resmi membuka babak baru dengan meresmikan kantor pusatnya di kawasan Rempoa, Ciputat Timur, Tangerang Selatan. Peresmian yang dirangkai dengan tasyakuran ini digelar pada 25 September 2026 dan menjadi tonggak penting bagi bank syariah yang telah hadir melayani masyarakat sejak 1989.\r\n\r\n<em>Gedung kantor pusat baru BSW berlokasi di Jl. Ir. H. Juanda No. 14, Rempoa, Ciputat Timur, Tangerang Selatan.</em>\r\n\r\n<img class=\"size-medium wp-image-176 aligncenter\" src=\"http://wakalumibprscoid.local/wp-content/uploads/2026/10/DSC01813-300x169.jpg\" alt=\"\" width=\"300\" height=\"169\" />\r\n<h3>Dihadiri Regulator dan Mitra</h3>\r\nAcara dihadiri jajaran Otoritas Jasa Keuangan (OJK), pelaku usaha, tokoh masyarakat, serta mitra strategis BSW. Kehadiran para tamu menegaskan posisi BSW sebagai lembaga keuangan syariah yang berkomitmen mendukung pertumbuhan ekonomi daerah dan pemberdayaan UMKM.\r\n\r\n<img class=\"size-medium wp-image-177 aligncenter\" src=\"http://wakalumibprscoid.local/wp-content/uploads/2026/10/DSC01948-300x169.jpg\" alt=\"\" width=\"300\" height=\"169\" />\r\n<h3>Memperkuat Layanan</h3>\r\nPerpindahan ke gedung baru diharapkan memperkuat kapabilitas operasional, memperluas jangkauan layanan, dan menghadirkan pengalaman perbankan syariah yang lebih modern dan terintegrasi bagi nasabah.\r\n<h3><img class=\"size-medium wp-image-153 aligncenter\" src=\"http://wakalumibprscoid.local/wp-content/uploads/2026/10/LOGO-WAQF-1-300x300.png\" alt=\"\" width=\"300\" height=\"300\" /></h3>\r\n<h3>Nilai #WAQF sebagai Landasan</h3>\r\nDalam kesempatan itu, nilai budaya perusahaan #WAQF (<em>Wisdom, Accountability, Quality, Foresight</em>) kembali ditegaskan sebagai landasan pertumbuhan. Kantor pusat baru diharapkan tidak sekadar menjadi fasilitas fisik, tetapi pusat inklusi keuangan syariah bagi masyarakat dan wirausahawan lokal. [SESUAIKAN sesuai foto asli]\r\n<h3><img class=\"size-medium wp-image-175 aligncenter\" src=\"http://wakalumibprscoid.local/wp-content/uploads/2026/10/DSC01800-300x169.jpg\" alt=\"\" width=\"300\" height=\"169\" /></h3>\r\n<h3>Mulai Beroperasi</h3>\r\nLayanan operasional dari kantor pusat baru berlaku efektif sejak Senin, 12 Oktober 2026.\r\n\r\n<hr />\r\n\r\n<small><em>Sumber rujukan: <a href=\"https://campusnet.news/perkuat-ekosistem-keuangan-syariah-bank-syariah-wakalumi-resmikan-kantor-pusat-baru-di-rempoa-ciputat\" target=\"_blank\" rel=\"noopener noreferrer\">CampusNet News</a></em></small>','Perkuat Ekosistem Keuangan Syariah, Bank Syariah Wakalumi Resmikan Kantor Pusat Baru di Rempoa','BSW meresmikan kantor pusat baru di Rempoa, Ciputat Timur, melalui acara tasyakuran pada 25 September 2026.','publish','closed','closed','','bsw-resmikan-kantor-pusat-baru-di-rempoa-ciputat','','','2026-10-26 02:48:01','2026-10-25 19:48:01','',0,'http://wakalumibprscoid.local/berita/bsw-resmikan-kantor-pusat-baru-di-rempoa-ciputat/',0,'berita','',0);
INSERT INTO `wp_posts` VALUES (161,0,'2026-10-13 02:34:36','2026-10-13 03:00:00','<strong>TANGERANG SELATAN</strong> — Seiring pembukaan kantor pusat baru, Bank Syariah Wakalumi memperkenalkan identitas baru dengan nama brand <strong>BSW</strong>. Nama sebelumnya, WAKALUMI (BPRS Wakalumi), kini bertransformasi menjadi Bank Syariah Wakalumi dengan logo yang lebih ringkas dan berkarakter.\r\n\r\n<img class=\"size-medium wp-image-149 aligncenter\" src=\"http://wakalumibprscoid.local/wp-content/uploads/2026/10/LOGO-BSW-BARU-modified-bprs-outline-putih-300x132.png\" alt=\"\" width=\"300\" height=\"132\" />\r\n\r\nLogo baru mengambil inspirasi dari kemurnian air yang dipadukan dengan huruf <em>wau</em> (و) sebagai inisial bank. Warna hijau tosca dan putih dipilih untuk mewakili bisnis, syariah, dan kemurnian, serta melambangkan amanah, transparansi, dan komitmen berkelanjutan.\r\n\r\n<img class=\"size-medium wp-image-152 aligncenter\" src=\"http://wakalumibprscoid.local/wp-content/uploads/2026/10/LOGO-WAQF-light-300x300.png\" alt=\"\" width=\"300\" height=\"300\" />\r\n\r\nPerubahan ini ditujukan agar identitas perusahaan lebih mudah diingat dan memperkuat posisi BSW di tengah masyarakat. Meski tampilan berubah, nilai #WAQF (<em>Wisdom, Accountability, Quality, Foresight</em>) tetap menjadi pedoman dalam setiap layanan.','Bertransformasi Jadi BSW, Bank Syariah Wakalumi Perkenalkan Logo Baru Bernuansa Hijau Tosca','BSW memperkenalkan identitas visual baru yang terinspirasi kemurnian air dan huruf wau.','publish','closed','closed','','bsw-perkenalkan-identitas-baru-bank-syariah-wakalumi','','','2026-10-26 02:34:36','2026-10-25 19:34:36','',0,'http://wakalumibprscoid.local/berita/bsw-perkenalkan-identitas-baru-bank-syariah-wakalumi/',0,'berita','',0);
INSERT INTO `wp_posts` VALUES (162,0,'2026-09-30 14:29:20','2026-09-30 07:00:00','<strong>TANGERANG SELATAN</strong> — Dalam upaya menjaga kualitas dan akurasi pelaporan, perwakilan Bank Syariah Wakalumi (BSW) mengikuti bimbingan teknis pelaporan Sistem Layanan Informasi Keuangan (SLIK) kepada Otoritas Jasa Keuangan (OJK).\r\n\r\nKegiatan ini membahas ketentuan dan tata cara pelaporan SLIK sebagai bagian dari penguatan tata kelola dan kepatuhan lembaga keuangan. Dengan pemahaman teknis yang lebih baik, BSW berharap proses pelaporan berjalan lebih tertib, akurat, dan tepat waktu.\r\n\r\nKegiatan ini sejalan dengan nilai <em>Accountability</em> dan <em>Quality</em> dalam budaya perusahaan #WAQF.','Tingkatkan Kualitas Pelaporan, Tim BSW Ikuti Bimbingan Teknis SLIK OJK','Perwakilan BSW mengikuti bimbingan teknis pelaporan SLIK ke OJK untuk memperkuat kualitas data dan kepatuhan.','publish','closed','closed','','tim-bsw-ikuti-bimtek-pelaporan-slik-ojk','','','2026-10-28 14:29:20','2026-10-28 07:29:20','',0,'http://wakalumibprscoid.local/berita/tim-bsw-ikuti-bimtek-pelaporan-slik-ojk/',0,'berita','',0);
INSERT INTO `wp_posts` VALUES (163,0,'2026-09-28 14:39:02','2026-09-28 04:00:00','<strong>TANGERANG SELATAN</strong> — Bank Syariah Wakalumi (BSW) mengikuti Focus Group Discussion (FGD) mengenai penerapan Cadangan Kerugian Penurunan Nilai (CKPN) berbasis SAK-EP. Penerapan ketentuan ini direncanakan mulai berlaku pada 1 Januari 2027.\r\n\r\n<img class=\" wp-image-172 alignright\" src=\"http://wakalumibprscoid.local/wp-content/uploads/2026/10/WhatsApp-Image-2026-10-26-at-2.37.58-AM-300x225.jpeg\" alt=\"\" width=\"410\" height=\"307\" />\r\n\r\nMelalui diskusi tersebut, BSW memperdalam pemahaman atas konsep dan kesiapan implementasi, baik dari sisi kebijakan, data, maupun sistem pendukung. Persiapan yang dilakukan sejak dini diharapkan membuat transisi berjalan lancar.\r\n\r\nLangkah ini mencerminkan nilai <em>Foresight</em> dan <em>Wisdom</em> dalam budaya perusahaan #WAQF.','Siapkan Penerapan CKPN SAK-EP, BSW Ikuti Focus Group Discussion','BSW mengikuti FGD terkait Cadangan Kerugian Penurunan Nilai (CKPN) berbasis SAK-EP sebagai persiapan penerapan mulai 1 Januari 2027.','publish','closed','closed','','bsw-siapkan-penerapan-ckpn-sak-ep-2027','','','2026-10-28 14:39:02','2026-10-28 07:39:02','',0,'http://wakalumibprscoid.local/berita/bsw-siapkan-penerapan-ckpn-sak-ep-2027/',0,'berita','',0);
INSERT INTO `wp_posts` VALUES (164,0,'2026-10-20 02:33:11','2026-10-20 01:30:00','Setiap lembaga memiliki nilai yang menjadi pegangan. Di Bank Syariah Wakalumi (BSW), nilai itu dirangkum dalam <strong>#WAQF</strong>:\r\n<ul>\r\n 	<li><strong>Wisdom (Kebijaksanaan):</strong> mengambil keputusan dengan pertimbangan matang dan sesuai prinsip syariah.</li>\r\n 	<li><strong>Accountability (Akuntabilitas):</strong> bertanggung jawab atas amanah nasabah dan mitra.</li>\r\n 	<li><strong>Quality (Kualitas):</strong> menghadirkan layanan terbaik secara konsisten.</li>\r\n 	<li><strong>Foresight (Visi ke Depan):</strong> melihat jauh dan bersiap menghadapi perubahan.</li>\r\n</ul>\r\nSejak hadir pada 1989, nilai ini menjadi landasan BSW dalam melayani masyarakat dan mendukung pertumbuhan UMKM. Nilai yang sama kembali ditegaskan saat peresmian kantor pusat baru pada 25 September 2026.','Mengenal #WAQF, Nilai Budaya yang Menjadi Landasan Bank Syariah Wakalumi','#WAQF — Wisdom, Accountability, Quality, Foresight — adalah nilai yang memandu setiap layanan BSW.','publish','closed','closed','','mengenal-budaya-perusahaan-waqf-bank-syariah-wakalumi','','','2026-10-26 02:33:11','2026-10-25 19:33:11','',0,'http://wakalumibprscoid.local/berita/mengenal-budaya-perusahaan-waqf-bank-syariah-wakalumi/',0,'berita','',0);
INSERT INTO `wp_posts` VALUES (165,0,'2026-10-18 02:33:25','2026-10-18 02:00:00','<strong>TANGERANG SELATAN</strong> — Komitmen Bank Syariah Wakalumi (BSW) dalam mempercepat transformasi layanan digital dan memperluas kemudahan bagi nasabah kembali diwujudkan. BSW resmi meluncurkan fasilitas <strong>Pembayaran Angsuran via Virtual Account (VA)</strong> berkat sinergi kemitraan bersama Bank Permata Syariah.\r\n\r\nFasilitas ini memberikan kenyamanan optimal bagi seluruh nasabah debitur pembiayaan BSW untuk menunaikan kewajiban pembayaran angsuran kapan saja dan dari mana saja secara <em>real-time</em> 24 jam sehari, 7 hari seminggu tanpa harus mendatangi kantor cabang.\r\n<h3>Format Nomor Rekening &amp; Skema Open Payment</h3>\r\nPembayaran Virtual Account BSW dapat dilakukan melalui ATM dan Mobile Banking dari bank mana pun di seluruh Indonesia (seperti PermataMobile X, BCA Mobile, Livin by Mandiri, BRImo, BNI Mobile, BSI Mobile, CIMB Octo, dan jaringan ATM Bersama / Prima / ALTO).\r\n<ul>\r\n 	<li><strong>Bank Tujuan:</strong> Bank Permata Syariah (Kode Bank: <strong>013</strong>).</li>\r\n 	<li><strong>Format Nomor VA:</strong> <code>728262 + Nomor Rekening Debitur Wakalumi</code> (Contoh: <code>7282621080199999</code>).</li>\r\n 	<li><strong>Skema Input Nominal Manual:</strong> Mengingat sistem menggunakan metode <em>Open Payment</em>, nominal tagihan angsuran tidak muncul otomatis di layar aplikasi. Nasabah wajib mengetik sendiri jumlah transfer angsurannya secara manual.</li>\r\n 	<li><strong>Biaya Admin Rp 3.500:</strong> Nasabah wajib menambahkan biaya admin switching transfer sebesar Rp 3.500 ke dalam saldo transfer agar dana pokok dan bagi hasil angsuran masuk utuh ke rekening pembiayaan (Contoh: jika angsuran Rp 1.000.000, jumlah yang diketik transfer adalah Rp 1.003.500).</li>\r\n</ul>\r\nLayar konfirmasi bank pengirim akan otomatis memvalidasi Nama Nasabah/Debitur terdaftar di Bank Syariah Wakalumi.\r\n<h3>Layanan yang Tetap Humanis</h3>\r\nDi samping kemudahan kanal digital VA, BSW tetap menjalankan komitmen layanan tatap muka yang hangat serta fasilitas jemput setoran langsung ke pasar-pasar tradisional dan lokasi usaha mitra UMKM binaan.\r\n\r\nPanduan langkah-demi-langkah serta kalkulator simulasi transfer dapat diakses langsung oleh masyarakat melalui halaman <a href=\"http://wakalumibprscoid.local/layanan/\">Layanan Kami</a> di website resmi BSW.','Permudah Nasabah, Bank Syariah Wakalumi Hadirkan Layanan Pembayaran Angsuran via Virtual Account','BSW berkolaborasi dengan Bank Permata Syariah menghadirkan fasilitas Virtual Account (VA) untuk kemudahan setor angsuran secara real-time 24/7 melalui ATM dan Mobile Banking seluruh bank.','publish','closed','closed','','kemudahan-bayar-angsuran-bsw-hadirkan-layanan-virtual-account-24-jam','','','2026-10-26 02:33:25','2026-10-25 19:33:25','',0,'http://wakalumibprscoid.local/berita/kemudahan-bayar-angsuran-bsw-hadirkan-layanan-virtual-account-24-jam/',0,'berita','',0);
