INSERT INTO `wp_posts` VALUES (174,1,'2026-10-26 02:42:01','2026-10-25 19:42:01','<strong>TANGERANG SELATAN</strong> — Bank Syariah Wakalumi (BSW) mengikuti Focus Group Discussion (FGD) mengenai penerapan Cadangan Kerugian Penurunan Nilai (CKPN) berbasis SAK-EP. Penerapan ketentuan ini direncanakan mulai berlaku pada 1 Januari 2027.\r\n\r\n<img class=\"size-medium wp-image-172 aligncenter\" src=\"http://wakalumibprscoid.local/wp-content/uploads/2026/10/WhatsApp-Image-2026-10-26-at-2.37.58-AM-300x225.jpeg\" alt=\"\" width=\"300\" height=\"225\" />\r\n\r\nMelalui diskusi tersebut, BSW memperdalam pemahaman atas konsep dan kesiapan implementasi, baik dari sisi kebijakan, data, maupun sistem pendukung. Persiapan yang dilakukan sejak dini diharapkan membuat transisi berjalan lancar.\r\n\r\nLangkah ini mencerminkan nilai <em>Foresight</em> dan <em>Wisdom</em> dalam budaya perusahaan #WAQF. [SESUAIKAN]','Siapkan Penerapan CKPN SAK-EP, BSW Ikuti Focus Group Discussion','BSW mengikuti FGD terkait Cadangan Kerugian Penurunan Nilai (CKPN) berbasis SAK-EP sebagai persiapan penerapan mulai 1 Januari 2027.','inherit','closed','closed','','163-revision-v1','','','2026-10-26 02:42:01','2026-10-25 19:42:01','',163,'http://wakalumibprscoid.local/?p=174',0,'revision','',0);
