INSERT INTO `wp_posts` VALUES (234,1,'2026-10-28 13:55:43','2026-10-28 06:55:43','<strong>TANGERANG SELATAN</strong> — Bank Syariah Wakalumi (BSW) mengikuti Focus Group Discussion (FGD) mengenai penerapan Cadangan Kerugian Penurunan Nilai (CKPN) berbasis SAK-EP. Penerapan ketentuan ini direncanakan mulai berlaku pada 1 Januari 2027.\r\n\r\n<img class=\"size-medium wp-image-172 alignright\" src=\"http://wakalumibprscoid.local/wp-content/uploads/2026/10/WhatsApp-Image-2026-10-26-at-2.37.58-AM-300x225.jpeg\" alt=\"\" width=\"300\" height=\"225\" />\r\n\r\nMelalui diskusi tersebut, BSW memperdalam pemahaman atas konsep dan kesiapan implementasi, baik dari sisi kebijakan, data, maupun sistem pendukung. Persiapan yang dilakukan sejak dini diharapkan membuat transisi berjalan lancar.\r\n\r\nLangkah ini mencerminkan nilai <em>Foresight</em> dan <em>Wisdom</em> dalam budaya perusahaan #WAQF.','Siapkan Penerapan CKPN SAK-EP, BSW Ikuti Focus Group Discussion','BSW mengikuti FGD terkait Cadangan Kerugian Penurunan Nilai (CKPN) berbasis SAK-EP sebagai persiapan penerapan mulai 1 Januari 2027.','inherit','closed','closed','','163-revision-v1','','','2026-10-28 13:55:43','2026-10-28 06:55:43','',163,'http://wakalumibprscoid.local/?p=234',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (235,1,'2026-10-28 13:57:02','2026-10-28 06:57:02','<strong>TANGERANG SELATAN</strong> — Bank Syariah Wakalumi (BSW) mengikuti Focus Group Discussion (FGD) mengenai penerapan Cadangan Kerugian Penurunan Nilai (CKPN) berbasis SAK-EP. Penerapan ketentuan ini direncanakan mulai berlaku pada 1 Januari 2027.\r\n\r\n<img class=\" wp-image-172 alignright\" src=\"http://wakalumibprscoid.local/wp-content/uploads/2026/10/WhatsApp-Image-2026-10-26-at-2.37.58-AM-300x225.jpeg\" alt=\"\" width=\"410\" height=\"307\" />\r\n\r\nMelalui diskusi tersebut, BSW memperdalam pemahaman atas konsep dan kesiapan implementasi, baik dari sisi kebijakan, data, maupun sistem pendukung. Persiapan yang dilakukan sejak dini diharapkan membuat transisi berjalan lancar.\r\n\r\nLangkah ini mencerminkan nilai <em>Foresight</em> dan <em>Wisdom</em> dalam budaya perusahaan #WAQF.','Siapkan Penerapan CKPN SAK-EP, BSW Ikuti Focus Group Discussion','BSW mengikuti FGD terkait Cadangan Kerugian Penurunan Nilai (CKPN) berbasis SAK-EP sebagai persiapan penerapan mulai 1 Januari 2027.','inherit','closed','closed','','163-revision-v1','','','2026-10-28 13:57:02','2026-10-28 06:57:02','',163,'http://wakalumibprscoid.local/?p=235',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (236,1,'2026-10-28 14:29:20','2026-10-28 07:29:20','<strong>TANGERANG SELATAN</strong> — Dalam upaya menjaga kualitas dan akurasi pelaporan, perwakilan Bank Syariah Wakalumi (BSW) mengikuti bimbingan teknis pelaporan Sistem Layanan Informasi Keuangan (SLIK) kepada Otoritas Jasa Keuangan (OJK).\r\n\r\nKegiatan ini membahas ketentuan dan tata cara pelaporan SLIK sebagai bagian dari penguatan tata kelola dan kepatuhan lembaga keuangan. Dengan pemahaman teknis yang lebih baik, BSW berharap proses pelaporan berjalan lebih tertib, akurat, dan tepat waktu.\r\n\r\nKegiatan ini sejalan dengan nilai <em>Accountability</em> dan <em>Quality</em> dalam budaya perusahaan #WAQF.','Tingkatkan Kualitas Pelaporan, Tim BSW Ikuti Bimbingan Teknis SLIK OJK','Perwakilan BSW mengikuti bimbingan teknis pelaporan SLIK ke OJK untuk memperkuat kualitas data dan kepatuhan.','inherit','closed','closed','','162-revision-v1','','','2026-10-28 14:29:20','2026-10-28 07:29:20','',162,'http://wakalumibprscoid.local/?p=236',0,'revision','',0);
